(window.SCI_DATA = window.SCI_DATA || []).push({"id": "phy-3", "subject": "理化", "chapter": "第三章", "title": "波動與聲音", "total": 218, "levels": {"必考": 20, "常考": 10}, "secs": {"3-1": "波的傳播與特徵", "3-2": "聲音的形成", "3-3": "多變的聲音", "3-4": "聲波的傳播與應用"}, "mapname": {}, "concepts": [{"id": "k8", "name": "聲音的三要素：響度、音調、音色", "n": 45, "level": "必考", "sec": "3-3", "card": {"說明": "聲音的三大主觀聽覺特徵，分別由聲波的三個不同物理客觀量決定，三者彼此獨立無關。", "關鍵名詞": "<div class=\"kv\"><b>響度（音量）</b>：聲音的強弱大小，主要由<b>振幅</b>決定（振幅愈大、響度愈大），且隨傳播距離增加而衰減；單位為<b>分貝（dB）</b>。</div><div class=\"kv\"><b>音調</b>：聲音的高低尖沉，由<b>振動頻率</b>決定（頻率愈高、音調愈高），單位為<b>赫茲（Hz）</b>。</div><div class=\"kv\"><b>音色（音品）</b>：聲音的獨特發音特性，由<b>聲波波形</b>決定（波形不同、音色不同）。</div>", "因果／影響": "<div class=\"kv\">每增加 10 dB，聲音強度增為原來的 10 倍；增加 20 dB 增為 100 倍。</div><div class=\"kv\">「聞聲辨人」或分辨不同樂器即使演奏同曲調同音量，是依賴<b>音色（波形）</b>。</div>", "出處": "自修第 123–124 頁／講義第 96–99 頁。", "標示": "自修與講義皆列為整章最核心<b>【必考】</b>重點。"}, "imgs": [], "clusters": [{"t": "看圖判讀", "n": 19, "ids": ["s3-1", "s3-4", "s3-44", "s3-45", "s3-47", "s3-56", "s3-65", "s3-66", "s3-67", "s3-74", "s3-133", "s3-134", "s3-137", "s3-152", "s3-181", "s3-185", "s3-194", "s3-196", "s3-206"]}, {"t": "觀念判斷", "n": 26, "ids": ["s3-39", "s3-40", "s3-43", "s3-46", "s3-49", "s3-50", "s3-57", "s3-58", "s3-77", "s3-117", "s3-119", "s3-122", "s3-123", "s3-124", "s3-125", "s3-126", "s3-130", "s3-132", "s3-135", "s3-136", "s3-157", "s3-188", "s3-189", "s3-193", "s3-195", "s3-197"]}]}, {"id": "k7", "name": "聲速與環境影響因素", "n": 29, "level": "必考", "sec": "3-2", "card": {"說明": "聲波在不同物質中傳播速率不同，通則為「<b>固體 > 液體 > 氣體 > 真空（0）</b>」，介質緊密度與彈性愈佳，傳速愈快。在空氣中，氣溫與溼度愈高、順風時，聲速愈快。", "關鍵名詞": "<div class=\"kv\"><b>空氣聲速公式</b>：在乾燥無風的空氣中，攝氏 T°C 時的聲速為：</div><div class=\"kv\">v ＝ 331 ＋ 0.6T（m/s）</div>", "因果／影響": "<div class=\"kv\">15°C 時空氣聲速為 331 + 0.6 × 15 = 340 m/s。</div><div class=\"kv\">打雷時閃電（光速約 3 × 10⁸ m/s）與雷聲同時產生，但因光速遠大於聲速，人在遠處總是先看到閃電後才聽到雷聲。</div>", "出處": "自修第 113 頁／講義第 91–92 頁。", "標示": "講義主題 3 標記為<b>【重點】</b>，計算題<b>【必考】</b>。"}, "imgs": [], "clusters": [{"t": "看圖判讀", "n": 5, "ids": ["s3-99", "s3-113", "s3-178", "s3-179", "s3-180"]}, {"t": "計算題", "n": 12, "ids": ["s3-24", "s3-25", "s3-110", "s3-112", "s3-155", "s3-156", "s3-171", "s3-175", "s3-177", "s3-182", "s3-184", "s3-187"]}, {"t": "觀念判斷", "n": 12, "ids": ["s3-8", "s3-27", "s3-35", "s3-48", "s3-61", "s3-68", "s3-72", "s3-98", "s3-100", "s3-115", "s3-116", "s3-172"]}]}, {"id": "k11", "name": "超聲波（超音波）與次聲波", "n": 25, "level": "必考", "sec": "3-4", "card": {"說明": "人耳能聽到的聲波頻率範圍約在 <b>20～ 20000 Hz</b>（可聽聲）。超出此頻率範圍的波動，人耳無法聽見，但在相同環境介質中，其<b>傳播速率與一般聲音完全相同</b>。", "關鍵名詞": "<div class=\"kv\"><b>超聲波（超音波）</b>：頻率高於 20000 Hz 的聲波，具高頻率、波長短、束縮性佳、方向性佳、穿透力強等特性。</div><div class=\"kv\"><b>次聲波（次音波）</b>：頻率低於 20 Hz 的聲波，人耳雖聽不見，但大象、長頸鹿可用於長距離通訊。</div><div class=\"kv\"><b>聲納（SONAR）</b>：利用超聲波遇障礙物反射回來的時間差，探測物體位置與距離的儀器（公式：S = v × t/2）。</div>", "因果／影響": "蝙蝠夜間飛行捕食、海豚溝通、醫院產檢超音波、超音波清洗機、汽車倒車雷達皆為超聲波應用。", "出處": "自修第 138 頁／講義第 108–109 頁。", "標示": "自修與講義皆列為<b>【重點／生活必考題】</b>，不可與電磁波混淆。"}, "imgs": [], "clusters": [{"t": "看圖判讀", "n": 4, "ids": ["s3-64", "s3-80", "s3-146", "s3-147"]}, {"t": "計算題", "n": 5, "ids": ["s3-142", "s3-144", "s3-162", "s3-208", "s3-215"]}, {"t": "觀念判斷", "n": 16, "ids": ["s3-52", "s3-53", "s3-54", "s3-55", "s3-70", "s3-143", "s3-145", "s3-161", "s3-200", "s3-201", "s3-204", "s3-207", "s3-210", "s3-212", "s3-213", "s3-217"]}]}, {"id": "k4", "name": "週期波的物理量（波長、振幅、週期、頻率）", "n": 23, "level": "必考", "sec": "3-1", "card": {"說明": "介質受規律連續擾動產生的重複波形稱為週期波。波源每完成一次完整往復振動（經歷 4 個振幅），波形即向前推進一個波長。", "關鍵名詞": "<div class=\"kv\"><b>平衡位置</b>：介質未受外力擾動時的靜止基準線。</div><div class=\"kv\"><b>波峰／波谷</b>：橫波中質點偏離平衡位置最高／最低的點。</div><div class=\"kv\"><b>密部／疏部</b>：縱波中介質分子分布密度最大／最小的區域。</div><div class=\"kv\"><b>振幅</b>：由平衡位置到波峰或波谷的垂直距離，代表波所攜帶能量的大小（振幅愈大，能量愈大）。</div><div class=\"kv\"><b>波長（λ）</b>：波形重複一次的最小水平距離（橫波為相鄰兩波峰或兩波谷之距離；縱波為相鄰兩密部或兩疏部中心之距離）。</div><div class=\"kv\"><b>週期（T）</b>：波源或質點完成一次完整振動所需的時間，單位為秒（s），公式：T = t/n（時間除以波數）。</div><div class=\"kv\"><b>頻率（f）</b>：每 1 秒內所產生的波數或質點完成振動的次數，單位為赫茲（Hz）或 1/ s，公式：f = n/t。</div>", "因果／影響": "週期與頻率互為倒數關係（T × f = 1），振動愈快則頻率愈大、週期愈小。", "出處": "自修第 100–101 頁／講義第 80–81 頁。", "標示": "自修與講義皆列為核心<b>【重點／必考】</b>。"}, "imgs": [], "clusters": [{"t": "看圖判讀", "n": 19, "ids": ["s3-5", "s3-12", "s3-15", "s3-16", "s3-17", "s3-29", "s3-31", "s3-32", "s3-34", "s3-36", "s3-71", "s3-88", "s3-92", "s3-93", "s3-94", "s3-150", "s3-151", "s3-165", "s3-166"]}, {"t": "計算題", "n": 2, "ids": ["s3-14", "s3-168"]}, {"t": "觀念判斷", "n": 2, "ids": ["s3-96", "s3-198"]}]}, {"id": "k5", "name": "波速公式與傳播規律", "n": 21, "level": "必考", "sec": "3-1", "card": {"說明": "波速即波形在介質中傳播的快慢程度。<b>波速大小完全由介質種類與狀態決定，與頻率、週期、振幅均無關</b>；而<b>頻率僅由波源振動快慢決定，波離開波源進入不同介質時頻率固定不變</b>。", "關鍵名詞": "<div class=\"kv\"><b>波速（v）</b>：波在單位時間內所傳播的直線距離，公式為：</div><div class=\"kv\">v ＝ L ÷ t ＝ λ ÷ T ＝ f × λ</div>", "因果／影響": "<div class=\"kv\"><b>同介質中</b>：波速 v 為定值，因此頻率 f 與波長 λ 成<b>反比</b>（波源晃得快，波長變短）。</div><div class=\"kv\"><b>不同介質中</b>：頻率 f 維持不變，波速 v 改變，波長 λ 與波速 v 成<b>正比</b>。</div>", "出處": "自修第 101 頁／講義第 79、81 頁。", "標示": "講義「老師的話」特別標記為最經典<b>【易錯／必考】</b>觀念。"}, "imgs": [], "clusters": [{"t": "看圖判讀", "n": 9, "ids": ["s3-6", "s3-33", "s3-37", "s3-38", "s3-76", "s3-87", "s3-89", "s3-167", "s3-169"]}, {"t": "計算題", "n": 6, "ids": ["s3-10", "s3-23", "s3-28", "s3-158", "s3-183", "s3-216"]}, {"t": "觀念判斷", "n": 6, "ids": ["s3-22", "s3-114", "s3-173", "s3-192", "s3-211", "s3-218"]}]}, {"id": "k6", "name": "聲音的產生與傳播條件", "n": 21, "level": "必考", "sec": "3-2", "card": {"說明": "聲音是由物體快速振動所產生的波動（聲源）。聲波必須依賴彈性介質分子相互碰撞擠壓以疏密波方式傳遞，在真空中無法傳播。", "關鍵名詞": "<div class=\"kv\"><b>聲源</b>：快速振動發出聲音的物體（如敲擊的音叉、振動的聲帶、樂器的弦）。</div><div class=\"kv\"><b>波以耳抽氣實驗</b>：英國科學家波以耳將鈴鐺置於密封玻璃罩內並抽氣，隨空氣抽出鈴聲漸弱至消失，證實聲音傳播需要空氣介質。</div>", "因果／影響": "用手按住正在發聲的音叉或鼓面，物體停止振動，聲音便立即停止。", "出處": "自修第 112 頁／講義第 87、89 頁。", "標示": "自修標為<b>【重點1、2】</b>，會考實驗題經典<b>【必考】</b>。"}, "imgs": [], "clusters": [{"t": "看圖判讀", "n": 4, "ids": ["s3-2", "s3-21", "s3-101", "s3-108"]}, {"t": "觀念判斷", "n": 17, "ids": ["s3-19", "s3-20", "s3-26", "s3-59", "s3-75", "s3-78", "s3-102", "s3-103", "s3-104", "s3-105", "s3-106", "s3-107", "s3-109", "s3-111", "s3-153", "s3-170", "s3-176"]}]}, {"id": "k9", "name": "發聲體的音調調控規律與共振", "n": 20, "level": "必考", "sec": "3-3", "card": {"說明": "物體的自然振動頻率取決於其長短、粗細、鬆緊、厚薄與材質。當兩物體振動頻率完全相同時，敲擊其中一個，另一個也會因能量傳遞跟著振動發聲，此現象稱為共振（共鳴）。", "關鍵名詞": "<div class=\"kv\"><b>共振（共鳴）</b>：當兩發聲體振動頻率相同時，一體發聲引起另一體共振的現象；樂器的「共鳴箱」即利用空氣共振放大音量。</div><div class=\"kv\"><b>發聲體音調規則</b>：發聲體愈<b>輕、薄、短、小、細、緊</b>，振動頻率愈高，音調愈高。</div>", "因果／影響": "<div class=\"kv\"><b>吹奏試管／排笛</b>：振動體為「<b>空氣柱</b>」，水量愈多者空氣柱愈短，吹奏音調愈<b>高</b>。</div><div class=\"kv\"><b>敲擊裝水試管</b>：振動體為「<b>水與試管壁</b>」，水量愈少者質量愈輕，敲擊音調愈<b>高</b>。</div>", "出處": "自修第 124 頁／講義第 98 頁。", "標示": "講義「老師的話」列為實驗題常考<b>【易錯／必考】</b>。"}, "imgs": [], "clusters": [{"t": "看圖判讀", "n": 11, "ids": ["s3-7", "s3-41", "s3-62", "s3-63", "s3-69", "s3-79", "s3-118", "s3-120", "s3-127", "s3-128", "s3-191"]}, {"t": "計算題", "n": 1, "ids": ["s3-190"]}, {"t": "觀念判斷", "n": 8, "ids": ["s3-42", "s3-60", "s3-73", "s3-121", "s3-129", "s3-131", "s3-159", "s3-163"]}]}, {"id": "k10", "name": "聲波的反射與回聲（回音）", "n": 15, "level": "常考", "sec": "3-4", "card": {"說明": "聲波前進遇到障礙物界面折回原介質的現象稱為反射，反射回來的聲音稱為回聲。回聲反射遵循<b>反射定律</b>（入射角等於反射角）。原聲與回聲在同一介質中傳播，其<b>聲速、頻率、波長、週期、音色完全不變</b>，僅<b>傳播方向改變</b>且<b>振幅（響度）因能量被吸收而變小</b>。", "關鍵名詞": "<div class=\"kv\"><b>回聲干擾與分辨條件</b>：原聲與回聲到達人耳的時間差需達 <b>0.1 秒以上</b>，人耳才能分辨兩聲；在 15°C 空氣中（聲速 340 m/s），發聲體與障礙物最小距離需為：</div><div class=\"kv\">S ＝ v × t ÷ 2 ＝ 340 × 0.1 ÷ 2 ＝ 17 公尺</div><div class=\"kv\"><b>吸音與防噪</b>：表面柔軟、多孔、粗糙（如窗簾、布幔、木質吸音板、凹凸不平壁面）容易吸收聲波，減弱回聲干擾。</div>", "因果／影響": "在小房間內說話，因原聲與回聲反射重疊時間小於 0.1 秒，聲音聽起來比空曠處更為響亮充實。", "出處": "自修第 137 頁／講義第 106–107 頁。", "標示": "講義與自修皆標記為<b>【重點／必考】</b>，原聲回聲性質比較為典型<b>【易錯】</b>陷阱。"}, "imgs": [], "clusters": [{"t": "看圖判讀", "n": 1, "ids": ["s3-138"]}, {"t": "計算題", "n": 4, "ids": ["s3-148", "s3-149", "s3-202", "s3-214"]}, {"t": "觀念判斷", "n": 10, "ids": ["s3-3", "s3-51", "s3-139", "s3-140", "s3-141", "s3-160", "s3-199", "s3-203", "s3-205", "s3-209"]}]}, {"id": "k1", "name": "波的形成與傳播特性", "n": 12, "level": "常考", "sec": "3-1", "card": {"說明": "物質受到擾動時所產生的凸起、凹下或疏鬆緊密部分稱為波，向外傳遞的現象即為波動。<b>波只傳遞能量與波形，不傳遞介質</b>；介質質點僅在原處附近作規則往復運動，絕不會隨波向前移動。", "關鍵名詞": "<div class=\"kv\"><b>波源</b>：造成物質擾動發出波的來源（振源）。</div><div class=\"kv\"><b>介質</b>：傳遞波動的媒介物質（如水、繩子、彈簧、空氣等）。</div>", "因果／影響": "因為介質不隨波前進，水面上的浮標或落葉只會在原地上下浮動，無法靠水波傳遞到岸邊。", "出處": "自修第 97 頁／講義第 77、79 頁。", "標示": "講義與自修皆列為<b>【重點】</b>，且為歷屆選擇題高頻率<b>【易錯】</b>觀念。"}, "imgs": [], "clusters": [{"t": "看圖判讀", "n": 5, "ids": ["s3-13", "s3-90", "s3-95", "s3-97", "s3-164"]}, {"t": "觀念判斷", "n": 7, "ids": ["s3-11", "s3-81", "s3-82", "s3-83", "s3-84", "s3-154", "s3-186"]}]}, {"id": "k3", "name": "橫波與縱波", "n": 6, "level": "一般", "sec": "3-1", "card": {"說明": "依波動前進方向與介質質點振動方向的幾何關係分類。兩者在波形呈現與質點運動規律上有本質差異。", "關鍵名詞": "<div class=\"kv\"><b>橫波（高低波）</b>：介質振動方向與波前進方向<b>互相垂直</b>的波，外觀呈現高低起伏的波峰與波谷（如繩波、水波表面）。</div><div class=\"kv\"><b>縱波（疏密波）</b>：介質振動方向與波前進方向<b>互相平行</b>的波，外觀呈現疏密相間的分布（如空氣中聲波、水平壓縮彈簧波）。</div>", "因果／影響": "彈簧既可左右水平推拉產生縱波，也可上下甩動產生橫波，是少數能同時演示兩種波形的介質。", "出處": "自修第 98 頁／講義第 78、80 頁。", "標示": "自修與講義皆標示為<b>【重點／必考】</b>。"}, "imgs": [], "clusters": [{"t": "看圖判讀", "n": 1, "ids": ["s3-30"]}, {"t": "觀念判斷", "n": 5, "ids": ["s3-9", "s3-18", "s3-86", "s3-91", "s3-174"]}]}, {"id": "k2", "name": "力學波與非力學波（電磁波）", "n": 1, "level": "一般", "sec": "3-1", "card": {"說明": "依波動傳播時<b>是否需要介質</b>，可將波分為兩大類。力學波必須靠介質分子的碰撞或牽引才能傳遞；非力學波則可在真空中直接傳遞能量。", "關鍵名詞": "<div class=\"kv\"><b>力學波（機械波）</b>：需要依靠介質才能傳遞的波動（如水波、繩波、彈簧波、聲波）。</div><div class=\"kv\"><b>非力學波（電磁波）</b>：不需要介質、在真空中亦可傳遞的波動（如光波、無線電波、紅外線、紫外線、X射線）。</div>", "因果／影響": "太空中因為處於近乎真空的無介質狀態，太空人面對面無法直接用聲音對話，必須藉由無線電波通訊。", "出處": "自修第 97 頁／講義第 77 頁。", "標示": "自修與講義皆標示為<b>【重點】</b>。"}, "imgs": [], "clusters": [{"t": "觀念判斷", "n": 1, "ids": ["s3-85"]}]}], "questions": [{"id": "s3-1", "no": "1", "c": "k8", "src": "翰林 A卷 第9回 第 1 題", "st": "考卷", "pk": "hl-A-9", "pname": "翰林 A卷・第9回（第3～4章）", "pord": 1, "ctx": "", "fig": "", "q": "右圖為甲、乙、丙、丁四個聲波，有關此四個聲波的敘述，下列何者錯誤？", "o": ["甲的音調最高", "甲、丁的波長相同", "乙、丙的振幅相同", "四者在空氣中的波速相同"], "a": 0, "e": "看「相同時間內」的波數：乙的波最多、最密 → 乙的頻率最高、音調最高，所以 (A)「甲的音調最高」錯誤。\n甲、丁波數相同 → 頻率相同；同一介質波速相同，λ＝v÷f，所以波長也相同。\n乙、丙上下起伏的高度一樣 → 振幅相同。\n★ 示波器：疏密看音調、高低看響度、形狀看音色；同一介質波速一定相同。", "h": [], "rep": true, "img": "s3-q1", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-2", "no": "2", "c": "k6", "src": "翰林 A卷 第9回 第 2 題", "st": "考卷", "pk": "hl-A-9", "pname": "翰林 A卷・第9回（第3～4章）", "pord": 1, "ctx": "", "fig": "", "q": "聲音是一種波動，現有一發音頻率為 356 Hz 的音叉，以小槌敲擊音叉後，音叉振動發出的聲音在空氣中形成聲波向外傳播，如右圖所示，則下列敘述何者正確？", "o": ["聲音在空氣中形成聲波為橫波", "圖中 L 的長度表示聲波的波長", "愈用力敲擊音叉，L 的長度愈長", "愈快速敲擊音叉，音叉的發音頻率愈高"], "a": 1, "e": "音叉振動把空氣擠成「密部」和「疏部」，空氣分子振動方向和波前進方向平行 → 聲波是縱波（疏密波），(A) 錯。\n相鄰兩個密部的距離就是波長，所以 L 是波長，(B) 正確。\n用力敲 → 振幅變大、響度變大，波長不變，(C) 錯。\n音叉的頻率由音叉本身決定，敲得快慢不會改變頻率，(D) 錯。", "h": [], "rep": true, "img": "s3-q2", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-3", "no": "3", "c": "k10", "src": "翰林 A卷 第9回 第 3 題", "st": "考卷", "pk": "hl-A-9", "pname": "翰林 A卷・第9回（第3～4章）", "pord": 1, "ctx": "", "fig": "", "q": "下列哪一種聲音是人耳無法聽見或分辨的？", "o": ["在一般教室吶喊的回音", "敲擊頻率為 2000 Hz 音叉發出的聲音", "在山谷中吶喊的回音", "振動頻率為 358 Hz 的聲音"], "a": 0, "e": "人耳要分辨原聲和回聲，兩者要相差 0.1 秒以上，也就是牆壁要在 17 公尺以外（340×0.1÷2＝17）。\n一般教室不到 17 公尺，回音和原聲重疊在一起，人耳分辨不出來。\n2000 Hz、358 Hz 都在 20～20000 Hz 之內，聽得到；山谷夠寬，回音分辨得出來。\n★ 回音能分辨的條件：距離障礙物 17 公尺以上。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-4", "no": "4", "c": "k8", "src": "翰林 A卷 第9回 第 4 題", "st": "考卷", "pk": "hl-A-9", "pname": "翰林 A卷・第9回（第3～4章）", "pord": 1, "ctx": "", "fig": "", "q": "兩種不同的樂器發出聲音並連接上示波器，得到聲音的波形如右圖所示，則此兩種聲音的不同點為何？", "o": ["頻率", "音色", "速率", "波長"], "a": 1, "e": "兩個波形：高低（振幅）相同、疏密（週期）相同，但「形狀」不同。\n波形不同 → 音色不同。同一空氣中速率相同；頻率相同所以波長也相同。\n★ 聞聲辨人、分辨樂器，靠的都是音色（波形）。", "h": [], "rep": true, "img": "s3-q4", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-5", "no": "5", "c": "k4", "src": "翰林 A卷 第9回 第 5 題", "st": "考卷", "pk": "hl-A-9", "pname": "翰林 A卷・第9回（第3～4章）", "pord": 1, "ctx": "", "fig": "", "q": "右圖為緊繃繩子的振動位置與距離的關係圖，若波由 A 點傳播至 B 點需時 0.6 秒，則下列何者正確？", "o": ["繩波的波長為 10 公分", "振幅為 4 公分", "週期為 0.2 秒", "波速為 50 公分／秒"], "a": 2, "e": "A 到 B 之間剛好有 3 個完整的波，波走這段花了 0.6 秒。\n走 1 個波長所需時間就是週期：T＝0.6÷3＝0.2 秒 → (C) 正確。\n由圖讀：相鄰兩波峰相距 8 公分 → 波長 8 公分，(A) 錯；平衡位置到波峰高 3 公分 → 振幅 3 公分，(B) 錯。\n波速 v＝λ÷T＝8÷0.2＝40 公分／秒，(D) 錯。", "h": ["數一數 A 到 B 之間有幾個完整的波。", "波每走 1 個波長，剛好花 1 個週期。"], "rep": true, "img": "s3-q5", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-6", "no": "6", "c": "k5", "src": "翰林 A卷 第9回 第 6 題", "st": "考卷", "pk": "hl-A-9", "pname": "翰林 A卷・第9回（第3～4章）", "pord": 1, "ctx": "", "fig": "", "q": "如右圖，在同一介質中所產生的甲、乙兩波，則下列相關敘述何者正確？", "o": ["甲、乙波長比為 3：8", "甲、乙週期比為 3：4", "甲、乙頻率比為 3：4", "甲、乙波速比為 4：3"], "a": 1, "e": "甲：圖上 3 cm 是「半個波」→ 波長 6 cm；乙：8 cm 是「一個波」→ 波長 8 cm。\n甲：乙波長比＝6：8＝3：4，(A) 錯。\n同一介質 → 波速相同（1：1），(D) 錯。\n波速相同時，週期和波長成正比 → 週期比＝3：4，(B) 正確；頻率是週期的倒數 → 頻率比＝4：3，(C) 錯。\n★ 同介質：v 相同，λ 和 T 成正比、λ 和 f 成反比。", "h": ["先分辨圖上標示的是一個波還是半個波。", "同一介質中波速相同，λ＝v×T。"], "rep": true, "img": "s3-q6", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-7", "no": "7", "c": "k9", "src": "翰林 A卷 第9回 第 7 題", "st": "考卷", "pk": "hl-A-9", "pname": "翰林 A卷・第9回（第3～4章）", "pord": 1, "ctx": "", "fig": "", "q": "有關右圖吉他發音的敘述，下列何者正確？", "o": ["較細的弦每秒振動的次數較少", "撥弦的速率加快，可使發出聲音的頻率變大", "共鳴箱的目的是美化聲音的音色", "手按同一條弦線上乙處比按甲處再撥弦，發出之音調較高"], "a": 3, "e": "較細的弦振動較快 → 每秒振動次數較多，(A) 錯。\n撥弦快慢、用力大小不會改變頻率（只會改變響度），(B) 錯。\n共鳴箱的作用是共鳴、使聲音變大聲，不是美化音色，(C) 錯。\n按在乙處時，能振動的弦比較短 → 振動較快 → 音調較高，(D) 正確。\n★ 發聲體愈「輕、薄、短、小、細、緊」，音調愈高。", "h": [], "rep": true, "img": "s3-q7", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-8", "no": "8", "c": "k7", "src": "翰林 A卷 第9回 第 8 題", "st": "考卷", "pk": "hl-A-9", "pname": "翰林 A卷・第9回（第3～4章）", "pord": 1, "ctx": "", "fig": "", "q": "在室溫 25 °C 的乾燥室內，音調 262 Hz、50 dB 的聲音，傳到 10 公尺外氣溫 30 °C 的乾燥室外，下列敘述何者正確？", "o": ["聲速變快，音調變高", "聲速變慢，響度變小", "波長變長，音調不變", "週期變小，音速變快"], "a": 2, "e": "溫度由 25 °C 升到 30 °C → 聲速變快（每升 1 °C 快 0.6 m/s）。\n頻率由聲源決定，傳到哪裡都不變 → 音調不變、週期不變。\nλ＝v÷f，v 變大、f 不變 → 波長變長，(C) 正確。\n聲音傳得愈遠響度會變小，但 (B) 說聲速變慢是錯的；(A)(D) 說音調變高、週期變小也錯。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-9", "no": "9", "c": "k3", "src": "翰林 B卷 第5回 第 1 題", "st": "考卷", "pk": "hl-B-5", "pname": "翰林 B卷・第5回（3-1～3-2）", "pord": 2, "ctx": "", "fig": "", "q": "關於波動的現象，下列敘述何者正確？", "o": ["波動可以傳播能量，也可以傳播介質", "縱波又稱為高低波", "彈簧可以產生橫波，也可以產生縱波", "電磁波是縱波"], "a": 2, "e": "波只傳遞能量，不會把介質帶走，(A) 錯。\n縱波又叫「疏密波」；橫波才叫「高低波」，(B) 錯。\n彈簧左右推拉產生縱波、上下甩動產生橫波，兩種都可以，(C) 正確。\n電磁波不是縱波，(D) 錯。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-10", "no": "10", "c": "k5", "src": "翰林 B卷 第5回 第 2 題", "st": "考卷", "pk": "hl-B-5", "pname": "翰林 B卷・第5回（3-1～3-2）", "pord": 2, "ctx": "", "fig": "", "q": "若空氣中傳播速率為 340 公尺／秒，某聲波產生一次完整振動需時 0.5 秒，振幅為 0.1 公尺，試問其波長應為多少公尺？", "o": ["680", "340", "170", "34"], "a": 2, "e": "完整振動一次需時 0.5 秒 → 週期 T＝0.5 秒。\n波每走一個週期前進一個波長：λ＝v×T＝340×0.5＝170 公尺。\n振幅 0.1 公尺和波長無關，是用來混淆的條件。", "h": ["完整振動一次的時間叫什麼？", "λ＝v×T，振幅用不到。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-11", "no": "11", "c": "k1", "src": "翰林 B卷 第5回 第 3 題", "st": "考卷", "pk": "hl-B-5", "pname": "翰林 B卷・第5回（3-1～3-2）", "pord": 2, "ctx": "", "fig": "", "q": "關於波與介質的對應，下列何者錯誤？", "o": ["水波的介質是水", "彈簧波的介質是彈簧", "繩波的介質是繩子", "海浪的介質是風"], "a": 3, "e": "海浪是水面的波動，介質是「水」，不是風。風只是讓海水產生波浪的來源（波源）。\n水波→水、彈簧波→彈簧、繩波→繩子，都正確。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-12", "no": "12", "c": "k4", "src": "翰林 B卷 第5回 第 4 題", "st": "考卷", "pk": "hl-B-5", "pname": "翰林 B卷・第5回（3-1～3-2）", "pord": 2, "ctx": "", "fig": "", "q": "振動時繩子往復振動一次所需時間稱為週期，如右圖所示，介質振動一次的路徑應為何？", "o": ["A→B→C→D→E", "B→F→G→F→B", "A→F→C→E", "A→B→C→G→A"], "a": 1, "e": "繩波傳播時，繩上的每一點只在原處上下振動，不會左右移動。\n振動一次 → 從最高點 B 往下經過平衡點 F、到最低點 G，再經過 F 回到 B，路徑 B→F→G→F→B。\n(A)(C)(D) 都是左右移動，那是「波形」前進的方向，不是介質振動的路徑。\n★ 振動一次＝走 4 個振幅。", "h": [], "rep": true, "img": "s3-q12", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-13", "no": "13", "c": "k1", "src": "翰林 B卷 第5回 第 5 題", "st": "考卷", "pk": "hl-B-5", "pname": "翰林 B卷・第5回（3-1～3-2）", "pord": 2, "ctx": "", "fig": "", "q": "右圖是一向右前進的連續週期波。甲、乙、丙三點在此一瞬間的運動方向為何？", "o": ["甲向下，乙向上，丙向上", "甲向上，乙向下，丙向下", "甲向上，乙不動，丙向下", "甲向上，乙不動，丙向上"], "a": 0, "e": "判斷方法（微移法）：把波形沿前進方向（向右）稍微挪一點，看每一點的新高度。\n甲在波峰的左側（波峰剛通過）→ 波形右移後甲變低 → 向下。\n乙、丙在波峰右側的下坡（波谷剛通過、波峰快到了）→ 波形右移後變高 → 向上。\n答案：甲向下，乙向上，丙向上。\n★ 波向右走時：波峰「前面」的點往上、「後面」的點往下。", "h": [], "rep": true, "img": "s3-q13", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-14", "no": "14", "c": "k4", "src": "翰林 B卷 第5回 第 6 題", "st": "考卷", "pk": "hl-B-5", "pname": "翰林 B卷・第5回（3-1～3-2）", "pord": 2, "ctx": "", "fig": "", "q": "振動彈簧使其產生連續週期波，若 2 分鐘振動 180 次，則此彈簧波的頻率為多少赫茲（Hz）？", "o": ["1.5", "3", "90", "180"], "a": 0, "e": "頻率＝每秒振動的次數。\n2 分鐘＝120 秒，f＝180÷120＝1.5 Hz。", "h": ["頻率是「每 1 秒」振動幾次。", "先把 2 分鐘換成秒。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-15", "no": "15", "c": "k4", "src": "翰林 B卷 第5回 第 7 題", "st": "考卷", "pk": "hl-B-5", "pname": "翰林 B卷・第5回（3-1～3-2）", "pord": 2, "ctx": "", "fig": "", "q": "當一連續週期波通過介質某一點時，此點必隨波形起伏，在其原先平衡位置的左右或上下做往返的運動。如右上圖所示，即為介質上某一點之位置座標(y)與時間(t)的關係曲線圖，則有關該連續波的敘述，下列何者正確？", "o": ["波長為 4 公分", "週期為 2 秒", "頻率為 10 赫", "振幅為 10 公分"], "a": 3, "e": "這是「位置－時間」圖，橫軸是時間，所以兩波峰的距離代表週期，不是波長。\n由圖：兩波峰相隔 4 秒 → 週期 4 秒，(B) 錯；頻率＝1÷4＝0.25 Hz，(C) 錯。\n最高點 10 公分 → 振幅 10 公分，(D) 正確。\n只有時間軸，看不出波長，(A) 錯。\n★ 先看橫軸是「時間」還是「距離」。", "h": [], "rep": true, "img": "s3-q15", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-16", "no": "16", "c": "k4", "src": "翰林 B卷 第5回 第 8 題", "st": "考卷", "pk": "hl-B-5", "pname": "翰林 B卷・第5回（3-1～3-2）", "pord": 2, "ctx": "", "fig": "", "q": "如右圖，有一波不斷向右傳播，頻率為 5 Hz，若某瞬間的波形如右圖，則下列敘述何者錯誤？", "o": ["波速為 36 公尺／分", "週期為 0.2 秒", "波長為 12 公分", "振幅為 8 公分"], "a": 3, "e": "振幅是「平衡位置到波峰」的高度：P（波峰）到 R（波谷）是 8 公分，振幅只有 4 公分 → (D) 錯誤，選它。\n波長：0 到 12 公分剛好一個波 → λ＝12 公分 (C) 正確。\n週期 T＝1÷5＝0.2 秒 (B) 正確；波速 v＝f×λ＝5×12＝60 公分／秒＝36 公尺／分 (A) 正確。", "h": ["振幅是波峰到平衡位置，不是波峰到波谷。", "v＝f×λ，再換成公尺／分。"], "rep": true, "img": "s3-q16", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-17", "no": "17", "c": "k4", "src": "翰林 B卷 第5回 第 9 題", "st": "考卷", "pk": "hl-B-5", "pname": "翰林 B卷・第5回（3-1～3-2）", "pord": 2, "ctx": "", "fig": "", "q": "右圖為頻率 10 赫的彈簧波，則有關此波的敘述，下列何者正確？", "o": ["此彈簧波屬於橫波", "波長為 30 cm", "波速為 100 cm/s", "週期為 0.1 秒"], "a": 3, "e": "彈簧左右疏密振動，振動方向與波前進方向平行 → 縱波，(A) 錯。\n圖中 30 cm 包含 1.5 個波 → 波長 20 cm，(B) 錯。\n波速 v＝f×λ＝10×20＝200 cm/s，(C) 錯。\n週期 T＝1÷10＝0.1 秒，(D) 正確。", "h": ["數一數 30 cm 內有幾個密部到密部的距離。", "週期＝1÷頻率。"], "rep": false, "img": "s3-q17", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-18", "no": "18", "c": "k3", "src": "翰林 B卷 第5回 第 10 題", "st": "考卷", "pk": "hl-B-5", "pname": "翰林 B卷・第5回（3-1～3-2）", "pord": 2, "ctx": "", "fig": "", "q": "有關波的性質，下列敘述何者正確？", "o": ["縱波為波的前進方向與介質振動方向平行", "振幅為波峰到波谷的距離", "繩波的傳遞屬於縱波", "波速的大小為波長除以頻率"], "a": 0, "e": "縱波：介質振動方向和波前進方向平行 → (A) 正確。\n振幅是平衡位置到波峰（或波谷）的距離，不是波峰到波谷，(B) 錯。\n繩波是橫波，(C) 錯。\n波速＝波長×頻率（或波長÷週期），(D) 錯。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-19", "no": "19", "c": "k6", "src": "翰林 B卷 第5回 第 11 題", "st": "考卷", "pk": "hl-B-5", "pname": "翰林 B卷・第5回（3-1～3-2）", "pord": 2, "ctx": "", "fig": "", "q": "關於聲音的傳播，下列敘述何者正確？", "o": ["火車在鐵軌上行駛的聲音，鐵軌不能傳播，完全要靠空氣傳播", "海面下沒有空氣，所以聲音不能傳播", "即使月球上有爆炸聲，也不能傳到地球來", "即使在真空中，聲音一樣可以傳播"], "a": 2, "e": "聲音可以在固體（鐵軌）、液體（海水）、氣體中傳播，(A)(B) 錯。\n月球和地球之間是真空，聲音無法傳過來 → (C) 正確；(D) 錯。\n★ 聲音一定要有介質，真空不傳聲。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-20", "no": "20", "c": "k6", "src": "翰林 B卷 第5回 第 12 題", "st": "考卷", "pk": "hl-B-5", "pname": "翰林 B卷・第5回（3-1～3-2）", "pord": 2, "ctx": "", "fig": "", "q": "下列何者為產生聲音的完整條件？", "o": ["在非真空的環境中使物體急速振動", "在真空的環境中使物體急速振動", "在非真空的環境中以固定的頻率敲擊物體", "在真空的環境中以固定的頻率敲擊物體"], "a": 0, "e": "產生並傳出聲音要有兩個條件：①物體振動 ②有介質（非真空）。\n敲擊不一定要固定頻率；真空中聽不到聲音。所以選 (A)。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-21", "no": "21", "c": "k6", "src": "翰林 B卷 第5回 第 13 題", "st": "考卷", "pk": "hl-B-5", "pname": "翰林 B卷・第5回（3-1～3-2）", "pord": 2, "ctx": "", "fig": "", "q": "取一電鈴放在裝有抽氣機的玻璃罩內，通電後，鈴鎚敲擊而發出聲音，如右圖所示，若將鐘罩內的空氣漸次抽出時，其聲音的變化為何？", "o": ["逐漸變強", "逐漸變弱", "忽強忽弱", "保持不變"], "a": 1, "e": "把罩內空氣抽掉，傳聲的介質愈來愈少，聽到的聲音逐漸變弱；接近真空時幾乎聽不到。\n鈴鎚還是在振動，只是聲音傳不出來。\n★ 抽氣實驗證明：聲音傳播需要介質。", "h": [], "rep": true, "img": "s3-q21", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-22", "no": "22", "c": "k5", "src": "翰林 B卷 第5回 第 14 題", "st": "考卷", "pk": "hl-B-5", "pname": "翰林 B卷・第5回（3-1～3-2）", "pord": 2, "ctx": "", "fig": "", "q": "在樂譜中可以看到 Do 有中央 C 或高音 C，兩個音階的唱名同為 Do，這兩個是相差八度的音，中央 C 的頻率為 262 赫茲，高音 C 的頻率為 524 赫茲。若兩者在相同條件空氣中的傳遞，波速分別為 V₁、V₂，則 V₁:V₂ 為多少？", "o": ["1：1", "1：2", "2：1", "4：1"], "a": 0, "e": "在相同的空氣中，聲速只由介質決定，和頻率高低無關。\n所以中央 C 和高音 C 的波速相同，V₁：V₂＝1：1。\n（頻率差 2 倍，改變的是波長：高音 C 的波長只有一半。）", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-23", "no": "23", "c": "k5", "src": "翰林 B卷 第5回 第 15 題", "st": "考卷", "pk": "hl-B-5", "pname": "翰林 B卷・第5回（3-1～3-2）", "pord": 2, "ctx": "", "fig": "", "q": "一音叉發出頻率為 50 赫的聲音，在空氣中傳播的速率為 340 公尺／秒，則此聲音的波長為多少公尺？", "o": ["6.8", "10", "17", "20"], "a": 0, "e": "λ＝v÷f＝340÷50＝6.8 公尺。", "h": ["波速、頻率、波長的關係是 v＝f×λ。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-24", "no": "24", "c": "k7", "src": "翰林 B卷 第5回 第 16 題", "st": "考卷", "pk": "hl-B-5", "pname": "翰林 B卷・第5回（3-1～3-2）", "pord": 2, "ctx": "", "fig": "", "q": "聲音 0 °C 時的速率為 331 公尺／秒，研究發現溫度每上升 1 °C，速率會增加 0.6 公尺／秒，在晴朗無風的天候狀況下，若當時的氣溫為 15 °C，則此時聲音的速率約為多少公尺／秒？", "o": ["420", "340", "330", "300"], "a": 1, "e": "空氣聲速公式：v＝331＋0.6T。\n15 °C：v＝331＋0.6×15＝331＋9＝340 公尺／秒。\n★ 口訣：零度三三一，每度加零點六。", "h": ["代入 v＝331＋0.6×溫度。"], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-25", "no": "25", "c": "k7", "src": "翰林 B卷 第5回 第 17 題", "st": "考卷", "pk": "hl-B-5", "pname": "翰林 B卷・第5回（3-1～3-2）", "pord": 2, "ctx": "", "fig": "", "q": "小里觀賞跨年煙火秀，看到煙火亮光後，經過 2 秒鐘才聽到爆炸聲。已知聲音和光在空氣中的傳播速率分別為 340 公尺／秒和 30 萬公里／秒，則煙火爆炸的地點與小里的距離約為多遠？", "o": ["170 公尺", "680 公尺", "15 萬公里", "60 萬公里"], "a": 1, "e": "光速極快，看到亮光的時間幾乎就是爆炸的時間，可以忽略。\n聲音走了 2 秒：距離＝340×2＝680 公尺。", "h": ["光傳過來的時間可以忽略嗎？", "距離＝聲速×時間。"], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-26", "no": "26", "c": "k6", "src": "翰林 B卷 第5回 第 18 題", "st": "考卷", "pk": "hl-B-5", "pname": "翰林 B卷・第5回（3-1～3-2）", "pord": 2, "ctx": "", "fig": "", "q": "在奧運中會有水上芭蕾的比賽項目，請問舞者在水中能聽到音樂聲嗎？", "o": ["能，因為水可以當作傳聲的介質", "不能，因為水不可以當作傳聲的介質", "能，因為音樂聲可以不經由介質傳播", "不能，舞者只能浮於水面時，才能由空氣聽到音樂聲"], "a": 0, "e": "液體也能傳聲，所以舞者在水中聽得到音樂。\n聲音一定要有介質才能傳播，(C) 錯；水是介質，(B)(D) 錯。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-27", "no": "27", "c": "k7", "src": "翰林 B卷 第5回 第 19 題", "st": "考卷", "pk": "hl-B-5", "pname": "翰林 B卷・第5回（3-1～3-2）", "pord": 2, "ctx": "", "fig": "", "q": "在空氣中，先後敲擊頻率分別為 100 Hz 與 200 Hz 的兩音叉，此兩音叉發出的聲音，傳入水中後傳播速率的比為何？", "o": ["1：1", "2：1", "1：2", "4：1"], "a": 0, "e": "聲速由介質決定，和頻率無關。兩個聲音都在水中傳播 → 速率相同，1：1。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-28", "no": "28", "c": "k5", "src": "翰林 B卷 第5回 第 20 題", "st": "考卷", "pk": "hl-B-5", "pname": "翰林 B卷・第5回（3-1～3-2）", "pord": 2, "ctx": "", "fig": "", "q": "小鼓的頻率為 500 Hz，若聲音傳播時，相鄰的密部距離為 70 cm，大鼓的頻率為 250 Hz，在相同的溫度條件下，則大鼓聲音的波長為多少 cm？", "o": ["35", "70", "140", "280"], "a": 2, "e": "相同溫度、同在空氣中 → 聲速相同，頻率和波長成反比。\n小鼓 500 Hz 的波長是 70 cm（相鄰密部距離）；大鼓 250 Hz 頻率變一半 → 波長變 2 倍＝140 cm。\n（也可以算：v＝500×70＝35000 cm/s，λ＝35000÷250＝140 cm。）", "h": ["相鄰密部的距離是什麼？", "同一介質波速相同，f 變一半時 λ 變幾倍？"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-29", "no": "29", "c": "k4", "src": "翰林 B卷 第5回 進階題 第 1 題", "st": "考卷", "pk": "hl-B-5", "pname": "翰林 B卷・第5回（3-1～3-2）", "pord": 2, "ctx": "", "fig": "", "q": "有一連續週期波，其傳播情形如右圖所示，若波源每秒產生 0.5 個波，則下列敘述何者錯誤？", "o": ["P 點回到平衡位置所需之最短時間為 0.5 秒", "此連續週期波的波速為 6 cm/s", "波形移動 6 cm 時，R 點移動 8 cm", "若週期減半，則相鄰波峰及波谷間的水平距離加倍"], "a": 3, "e": "由圖：波長 12 cm、振幅 4 cm；每秒產生 0.5 個波 → f＝0.5 Hz、T＝2 秒。\n(A) P 在波峰，回到平衡位置要 1/4 週期＝0.5 秒，正確。\n(B) v＝f×λ＝0.5×12＝6 cm/s，正確。\n(C) 波形移動 6 cm＝半個波長，花半個週期，每個質點走 2 個振幅＝8 cm，正確。\n(D) 週期減半 → 頻率加倍 → 波長減半，波峰到波谷的水平距離也減半，不是加倍 → 錯誤，選它。", "h": ["先讀出波長、振幅，再由「每秒 0.5 個波」得到頻率和週期。", "同一介質波速不變，週期變短時波長怎麼變？"], "rep": false, "img": "s3-q29", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-30", "no": "30", "c": "k3", "src": "翰林 B卷 第5回 進階題 第 2 題", "st": "考卷", "pk": "hl-B-5", "pname": "翰林 B卷・第5回（3-1～3-2）", "pord": 2, "ctx": "", "fig": "", "q": "右圖是波速 10 公分／秒的繩波，則有關該波的敘述何者錯誤？", "o": ["振幅為 10 公分", "週期為 4 秒", "其介質振動方式和在空氣中傳播的聲音相同", "波長為 40 公分"], "a": 2, "e": "這是位置－時間圖：最高 10 公分 → 振幅 10 公分 (A) 正確；兩波峰相隔 4 秒 → 週期 4 秒 (B) 正確。\n波長 λ＝v×T＝10×4＝40 公分 (D) 正確。\n繩波是橫波，空氣中的聲音是縱波，振動方式不同 → (C) 錯誤，選它。", "h": ["橫軸是時間，波峰到波峰是週期。", "λ＝v×T。"], "rep": true, "img": "s3-q30", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-31", "no": "31", "c": "k4", "src": "翰林 B卷 第5回 進階題 第 3 題", "st": "考卷", "pk": "hl-B-5", "pname": "翰林 B卷・第5回（3-1～3-2）", "pord": 2, "ctx": "", "fig": "", "q": "右圖為小新上下擺動繩子，經 0.1 秒後波傳遞的情形，波由 A 至 A₁ 共行進多少個波？", "o": ["1/4", "2/4", "3/4", "1"], "a": 0, "e": "由圖：A 到 A₁ 之間只有「波峰的一半」，也就是 1/4 個波（一個完整的波包含波峰和波谷）。\n所以 0.1 秒內波前進 1/4 個波。", "h": [], "rep": false, "img": "s3-q31", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-32", "no": "32", "c": "k4", "src": "翰林 B卷 第5回 進階題 第 4 題", "st": "考卷", "pk": "hl-B-5", "pname": "翰林 B卷・第5回（3-1～3-2）", "pord": 2, "ctx": "", "fig": "", "q": "承上題，請問此波的頻率為多少赫茲（Hz）？", "o": ["1/10", "1/4", "2", "2.5"], "a": 3, "e": "0.1 秒產生 1/4 個波 → 產生 1 個波要 0.4 秒 → 週期 T＝0.4 秒。\n頻率 f＝1÷0.4＝2.5 Hz。", "h": ["1/4 個波花 0.1 秒，1 個波花幾秒？", "頻率＝1÷週期。"], "rep": false, "img": "s3-q32", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-33", "no": "33", "c": "k5", "src": "翰林 B卷 第5回 進階題 第 5 題", "st": "考卷", "pk": "hl-B-5", "pname": "翰林 B卷・第5回（3-1～3-2）", "pord": 2, "ctx": "", "fig": "", "q": "承上題，請問此波的波速為多少公分／秒？", "o": ["0.4", "1", "10", "20"], "a": 2, "e": "由圖：一個完整的波從 0 到 4 公分 → 波長 4 公分。\nv＝f×λ＝2.5×4＝10 公分／秒。", "h": ["從圖上讀出一個完整波的長度。", "用上一題的頻率 2.5 Hz 代入 v＝f×λ。"], "rep": true, "img": "s3-q33", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-34", "no": "34", "c": "k4", "src": "翰林 B卷 第5回 素養題 第 1 題", "st": "考卷", "pk": "hl-B-5", "pname": "翰林 B卷・第5回（3-1～3-2）", "pord": 2, "ctx": "", "fig": "", "q": "右圖為相同材質的繩子在相同時間產生不同波形的示意圖，若格子的大小均為 1 公分，則甲、乙、丙、丁四圖各項的比，下列何者錯誤？", "o": ["波長比＝2：1：4：2", "波速比＝1：1：1：1", "振幅比＝4：2：2：3", "週期比＝2：4：1：2"], "a": 3, "e": "同材質的繩子 → 波速相同（1：1：1：1）。\n數格子：波長 甲 2、乙 1、丙 4、丁 2 → 2：1：4：2；振幅 甲 4、乙 2、丙 2、丁 3。\n波速相同時週期和波長成正比 → 週期比也是 2：1：4：2，所以 (D)「2：4：1：2」錯誤。\n（2：4：1：2 其實是頻率比。）", "h": ["同一種繩子，波速會不會相同？", "波速相同時，週期跟波長成正比還是反比？"], "rep": false, "img": "s3-q34", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-35", "no": "35", "c": "k7", "src": "翰林 B卷 第5回 素養題 第 2 題", "st": "考卷", "pk": "hl-B-5", "pname": "翰林 B卷・第5回（3-1～3-2）", "pord": 2, "ctx": "", "fig": "", "q": "當遠處爆竹工廠發生爆炸時，我們會先感受到何者？", "o": ["先感覺地面振動", "先聽到爆炸聲", "同時察覺到地面振動與爆炸聲", "視當時天氣情況而定"], "a": 0, "e": "聲波在固體中傳得最快（固體＞液體＞氣體）。\n爆炸的振動經由地面（固體）傳來比經由空氣快，所以先感覺到地面振動。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-36", "no": "36", "c": "k4", "src": "翰林 B卷 第5回 素養題 第 3 題", "st": "考卷", "pk": "hl-B-5", "pname": "翰林 B卷・第5回（3-1～3-2）", "pord": 2, "ctx": "", "fig": "", "q": "一條輕繩的一端固定於水平桌面的桌緣上，拉直此繩使其呈水平後，再以固定頻率鉛直上下振動，產生相同頻率的繩波，其示意圖如下圖所示。繩波上一點 P 與桌面水平線的鉛直高度與時間的關係如下表所示，依據此表推論，下列何者最可能是此繩波的週期及振幅？", "o": ["週期為 1.0 × 10⁻² s，振幅為 10 cm", "週期為 2.0 × 10⁻² s，振幅為 5 cm", "週期為 3.0 × 10⁻² s，振幅為 10 cm", "週期為 6.0 × 10⁻² s，振幅為 5 cm"], "a": 3, "e": "看表格中 P 點的高度：t＝0 時 5.0 cm，到 t＝6.0×10⁻² s 時又回到 5.0 cm 且動作相同 → 完成一次振動，週期 6.0×10⁻² s。\n高度在 ＋5.0 和 －5.0 之間變化 → 振幅 5 cm。\n★ 3.0×10⁻² s 時在最低點，只是半個週期。", "h": ["找出 P 點「回到原位置而且動作相同」的時間。", "最高與最低是 ±5.0，振幅是多少？"], "rep": false, "img": "s3-q36", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-37", "no": "37", "c": "k5", "src": "翰林 B卷 第5回 素養題 第 4 題", "st": "考卷", "pk": "hl-B-5", "pname": "翰林 B卷・第5回（3-1～3-2）", "pord": 2, "ctx": "", "fig": "", "q": "下圖為波速相等的甲、乙兩連續等振幅週期波，試問甲、乙兩波波長比為何？", "o": ["2：3", "3：2", "1：3", "3：1"], "a": 0, "e": "由圖：甲在 12 cm 內有 1.5 個波 → λ甲＝8 cm；乙 12 cm 剛好 1 個波 → λ乙＝12 cm。\nλ甲：λ乙＝8：12＝2：3。", "h": ["數一數 12 cm 內甲、乙各有幾個波。"], "rep": true, "img": "s3-q37", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-38", "no": "38", "c": "k5", "src": "翰林 B卷 第5回 素養題 第 5 題", "st": "考卷", "pk": "hl-B-5", "pname": "翰林 B卷・第5回（3-1～3-2）", "pord": 2, "ctx": "", "fig": "", "q": "承上題，甲、乙兩波週期比為何？", "o": ["2：1", "1：2", "2：3", "3：2"], "a": 2, "e": "波速相等時，λ＝v×T，週期和波長成正比。\nT甲：T乙＝λ甲：λ乙＝2：3。", "h": ["v 相同時，T 和 λ 成正比。"], "rep": true, "img": "s3-q38", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-39", "no": "39", "c": "k8", "src": "翰林 B卷 第6回 第 1 題", "st": "考卷", "pk": "hl-B-6", "pname": "翰林 B卷・第6回（3-3～3-4）", "pord": 3, "ctx": "", "fig": "", "q": "聲音傳經一段距離後，便不易聽清楚的原因為何？", "o": ["聲音頻率隨傳播時間之增長而降低", "聲音頻率愈來愈大", "聲音速度受空氣阻力影響而減慢", "聲音振動幅度隨範圍擴大而減小"], "a": 3, "e": "聲音向外擴散，能量分散到愈來愈大的範圍 → 振幅變小 → 響度變小。\n頻率、速度都不會因為傳得遠而改變。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-40", "no": "40", "c": "k8", "src": "翰林 B卷 第6回 第 2 題", "st": "考卷", "pk": "hl-B-6", "pname": "翰林 B卷・第6回（3-3～3-4）", "pord": 3, "ctx": "", "fig": "", "q": "合唱團分成高音部、中音部和低音部，這是根據團員聲音的何種性質？", "o": ["音調", "音色", "響度", "身高"], "a": 0, "e": "高音、中音、低音指的是聲音的高低 → 音調（頻率）。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-41", "no": "41", "c": "k9", "src": "翰林 B卷 第6回 第 3 題", "st": "考卷", "pk": "hl-B-6", "pname": "翰林 B卷・第6回（3-3～3-4）", "pord": 3, "ctx": "", "fig": "", "q": "在五支容量相同的量筒中，分別裝入不同高度的水，裝置如右圖所示，若用嘴吹不同水位的量筒，則發出的聲音音調由高而低的順序為何？", "o": ["E>D>C>B>A", "A>B>C>D>E", "B>A>D>C>E", "E>B>D>C>A"], "a": 0, "e": "用嘴吹量筒時，振動發聲的是「筒內的空氣柱」。\n水愈多 → 空氣柱愈短 → 振動愈快 → 音調愈高。E 水最多，A 水最少 → E＞D＞C＞B＞A。\n★ 用敲的話相反：振動的是水和筒，水愈少音調愈高。", "h": [], "rep": true, "img": "s3-q41", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-42", "no": "42", "c": "k9", "src": "翰林 B卷 第6回 第 4 題", "st": "考卷", "pk": "hl-B-6", "pname": "翰林 B卷・第6回（3-3～3-4）", "pord": 3, "ctx": "", "fig": "", "q": "彈奏弦樂器時，下列哪些方法可以提高音調？ (甲)用力彈；(乙)彈快一點；(丙)按弦按短一點；(丁)彈較粗的弦；(戊)將弦調緊。", "o": ["僅甲乙", "僅丙丁", "僅甲丁", "僅丙戊"], "a": 3, "e": "提高音調要讓弦振動得更快：按短一點（丙）、調緊一點（戊）、換細的弦。\n用力彈只會更大聲（響度），彈快一點不會改變頻率，粗弦音調反而較低 → 選僅丙戊。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-43", "no": "43", "c": "k8", "src": "翰林 B卷 第6回 第 5 題", "st": "考卷", "pk": "hl-B-6", "pname": "翰林 B卷・第6回（3-3～3-4）", "pord": 3, "ctx": "", "fig": "", "q": "甲、乙兩名學生先後敲擊同一支音叉，甲輕敲，乙重擊，則下列敘述何者正確？", "o": ["乙敲擊時，其音調較高", "乙敲擊時，聲速較快", "甲、乙的響度相同", "乙敲擊時，聲音可傳得較遠"], "a": 3, "e": "同一支音叉頻率固定，輕敲重敲音調都一樣，(A) 錯。\n同一介質聲速相同，(B) 錯。\n重擊振幅較大 → 響度較大 → 傳得較遠，(C) 錯、(D) 正確。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-44", "no": "44", "c": "k8", "src": "翰林 B卷 第6回 第 6 題", "st": "考卷", "pk": "hl-B-6", "pname": "翰林 B卷・第6回（3-3～3-4）", "pord": 3, "ctx": "", "fig": "", "q": "下列何者的音色與其他三者不同？", "o": ["圖A波形", "圖B波形", "圖C波形", "圖D波形"], "a": 1, "e": "(A)(C)(D) 都是平滑的單純波形，只有 (B) 是彎彎曲曲的複雜波形。\n波形不同 → 音色不同，所以選 (B)。", "h": [], "rep": true, "img": "s3-q44", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-45", "no": "45", "c": "k8", "src": "翰林 B卷 第6回 第 7 題", "st": "考卷", "pk": "hl-B-6", "pname": "翰林 B卷・第6回（3-3～3-4）", "pord": 3, "ctx": "", "fig": "", "q": "右圖為在 0.01 秒內所產生的甲、乙、丙、丁四聲波，其中音調相同而響度不同的為何？", "o": ["甲、乙", "乙、丙", "丙、丁", "甲、丁"], "a": 3, "e": "音調相同 → 相同時間內波的個數一樣（頻率相同）；響度不同 → 振幅不同。\n甲、丁的波數相同、高度不同 → 選甲、丁。", "h": [], "rep": true, "img": "s3-q45", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-46", "no": "46", "c": "k8", "src": "翰林 B卷 第6回 第 8 題", "st": "考卷", "pk": "hl-B-6", "pname": "翰林 B卷・第6回（3-3～3-4）", "pord": 3, "ctx": "", "fig": "", "q": "朝會時我們不用看就能分辨出訓導主任與生教組長的聲音，主要是因為兩種聲音有何不同？", "o": ["分貝數不同", "波形不同", "頻率不同", "聲速不同"], "a": 1, "e": "不同的人說話，聲音的波形不同 → 音色不同，所以能聞聲辨人。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-47", "no": "47", "c": "k8", "src": "翰林 B卷 第6回 第 9 題", "st": "考卷", "pk": "hl-B-6", "pname": "翰林 B卷・第6回（3-3～3-4）", "pord": 3, "ctx": "", "fig": "", "q": "常溫下，先後敲擊甲、乙、丙三音叉，得到的波形如右圖所示，則下列敘述何者正確？", "o": ["甲的響度最大，甲及丙的音調相同", "甲的音調最高，乙的波速最快", "甲和丙的週期相同，頻率不同", "三個音叉波速大小為乙>甲=丙"], "a": 0, "e": "甲的振幅最大 → 響度最大；甲、丙在 1/100 秒內波數相同 → 頻率相同、音調相同 → (A) 正確。\n乙的波最密 → 乙音調最高，(B) 錯；甲、丙週期相同頻率也相同，(C) 錯。\n同在空氣中，三者波速相同，(D) 錯。", "h": [], "rep": false, "img": "s3-q47", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-48", "no": "48", "c": "k7", "src": "翰林 B卷 第6回 第 10 題", "st": "考卷", "pk": "hl-B-6", "pname": "翰林 B卷・第6回（3-3～3-4）", "pord": 3, "ctx": "", "fig": "", "q": "三個人在教室內談話，李瑩聲音尖又高，宏達聲音宏亮大聲，建霖說話快又急，這些聲音在空氣中傳播開來，下列敘述何者錯誤？", "o": ["李瑩的聲音頻率最大", "建霖的聲速最快", "宏達的聲音響度最大", "宏達的聲音可傳得最遠"], "a": 1, "e": "聲速只由介質決定，說話快慢和聲速無關 → (B)「建霖的聲速最快」錯誤，選它。\n尖又高 → 頻率大；宏亮大聲 → 響度大、傳得遠。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-49", "no": "49", "c": "k8", "src": "翰林 B卷 第6回 第 11 題", "st": "考卷", "pk": "hl-B-6", "pname": "翰林 B卷・第6回（3-3～3-4）", "pord": 3, "ctx": "", "fig": "", "q": "觀賞模仿節目時，我們會覺得模仿者的聲音很像本人，主要是因為__①__很像。當表演者撥動較細的琴弦，所發出的__②__也會愈高。請問在上面的敘述中，空格①、②依序要填入什麼名詞？", "o": ["①：波形、②：響度", "①：頻率、②：響度", "①：波形、②：頻率", "①：響度、②：波形"], "a": 2, "e": "模仿得很像 → 聲音的「波形」（音色）很像。\n細弦振動快 → 頻率高 → 音調高。所以 ①波形、②頻率。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-50", "no": "50", "c": "k8", "src": "翰林 B卷 第6回 第 12 題", "st": "考卷", "pk": "hl-B-6", "pname": "翰林 B卷・第6回（3-3～3-4）", "pord": 3, "ctx": "", "fig": "", "q": "關於噪音的敘述，下列何者正確？(甲)分貝（dB）是響度的單位；(乙)婚喪喜慶、民俗活動不可為了達成活動目標，而不考慮噪音問題；(丙)改善噪音是政府的事，與個人無關。", "o": ["僅甲乙", "僅乙丙", "僅甲丙", "甲乙丙"], "a": 0, "e": "(甲) 分貝是響度單位，正確。\n(乙) 活動也要顧及噪音，正確。\n(丙) 改善噪音人人有責，不只是政府的事，錯誤。→ 僅甲乙。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-51", "no": "51", "c": "k10", "src": "翰林 B卷 第6回 第 13 題", "st": "考卷", "pk": "hl-B-6", "pname": "翰林 B卷・第6回（3-3～3-4）", "pord": 3, "ctx": "", "fig": "", "q": "將聲音的原聲和回聲互相比較，兩者不同之處為何？", "o": ["振幅", "振幅、週期、頻率", "振幅、週期、頻率、速率", "振幅、波長、週期、頻率、速率"], "a": 0, "e": "原聲和回聲在同一介質中，速率、頻率、週期、波長、音色都不變。\n回聲傳得較遠、部分能量被障礙物吸收 → 振幅變小（響度變小）。\n所以只有振幅不同（另外方向也改變）。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-52", "no": "52", "c": "k11", "src": "翰林 B卷 第6回 第 14 題", "st": "考卷", "pk": "hl-B-6", "pname": "翰林 B卷・第6回（3-3～3-4）", "pord": 3, "ctx": "", "fig": "", "q": "關於聲音的敘述，下列何者錯誤？", "o": ["聲音是由物體產生振動後，經由介質向外傳播", "聽不見遠處說話的原因，是因為聲音的振幅漸小", "人的耳朵可聽見 200000 赫以內所有頻率的聲音", "將吉他弦線拉緊，撥弦時弦線每秒振動的次數會較未拉緊時增加"], "a": 2, "e": "人耳能聽到的範圍是 20～20000 Hz，不是 200000 Hz → (C) 錯誤，選它。\n弦拉緊 → 振動變快 → 每秒振動次數增加，(D) 正確。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-53", "no": "53", "c": "k11", "src": "翰林 B卷 第6回 第 15 題", "st": "考卷", "pk": "hl-B-6", "pname": "翰林 B卷・第6回（3-3～3-4）", "pord": 3, "ctx": "", "fig": "", "q": "下列有關超聲波的敘述，何者正確？", "o": ["超聲波的傳播速率較一般聲波快", "只要音量夠大，人類就可以聽見該聲波", "超聲波可應用在清洗眼鏡的高頻震盪器", "超聲波可用於偵測魚群，主要是利用聲波折射的原理"], "a": 2, "e": "超聲波也是聲波，在同一介質中速率和一般聲波相同，(A) 錯。\n人耳聽不到是因為頻率太高（超過 20000 Hz），和音量無關，(B) 錯。\n超音波清洗機利用高頻振動清潔，(C) 正確。\n偵測魚群利用的是聲波「反射」，不是折射，(D) 錯。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-54", "no": "54", "c": "k11", "src": "翰林 B卷 第6回 第 16 題", "st": "考卷", "pk": "hl-B-6", "pname": "翰林 B卷・第6回（3-3～3-4）", "pord": 3, "ctx": "", "fig": "", "q": "下列何組聲音，人類一定聽不到？", "o": ["300 Hz、110 分貝", "3000 Hz、50 分貝", "30000 Hz、50 分貝", "3000 Hz、10 分貝"], "a": 2, "e": "人耳聽得到的頻率是 20～20000 Hz。30000 Hz 是超聲波，不管多大聲都聽不到 → (C)。\n3000 Hz、10 分貝雖然很小聲，但頻率在範圍內，還是聽得到。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-55", "no": "55", "c": "k11", "src": "翰林 B卷 第6回 第 17 題", "st": "考卷", "pk": "hl-B-6", "pname": "翰林 B卷・第6回（3-3～3-4）", "pord": 3, "ctx": "", "fig": "", "q": "醫師為孕婦探測腹中嬰兒健康與否，是利用下列何者？", "o": ["雷射光", "超音波", "紫外線", "X光"], "a": 1, "e": "產檢用的是超音波（超聲波），利用反射成像，對胎兒安全。\nX 光、紫外線對胎兒有害；雷射光不能穿透身體成像。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-56", "no": "56", "c": "k8", "src": "金安 A卷 第6次練習", "st": "考卷", "pk": "ja-6", "pname": "金安 A卷・第6次練習", "pord": 5, "ctx": "", "fig": "", "q": "聲波武器是利用聲音對人員造成殺傷或干擾的武器，用喇叭定向發出大量的聲波，使敵方人員死亡或喪失戰鬥力。研究發現，聽力的喪失以 4000 Hz 最容易發生。試根據下表判斷，戰鬥人員應如何調整聲波武器，最容易使敵人達到暫時性耳聾？", "o": ["4000 Hz、110 分貝", "4000 Hz、130 分貝", "20000 Hz、110 分貝", "2000 Hz、110 分貝"], "a": 0, "e": "表中 100～120 分貝會造成「暫時性耳聾」，超過 120 分貝就超出耳朵忍受範圍（可能永久受損）。\n題目說聽力喪失以 4000 Hz 最容易發生 → 選 4000 Hz、110 分貝。\n130 分貝已超過 120 分貝，不只是暫時性耳聾；20000 Hz、2000 Hz 不是最易受損的頻率。", "h": [], "rep": false, "img": "s3-q56", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-57", "no": "57", "c": "k8", "src": "金安 A卷 第6次練習", "st": "考卷", "pk": "ja-6", "pname": "金安 A卷・第6次練習", "pord": 5, "ctx": "", "fig": "", "q": "上課時，坐在教室後面的小丸子感覺請教前老師講解的聲音比較小，主要是因為聲波傳至教室後面時，下列何者變小？", "o": ["振幅", "頻率", "速率", "波長"], "a": 0, "e": "聲音傳得愈遠，能量分散，振幅變小 → 響度變小，所以坐後面聽起來比較小聲。\n頻率、速率、波長都不會因距離改變。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-58", "no": "58", "c": "k8", "src": "金安 A卷 第6次練習", "st": "考卷", "pk": "ja-6", "pname": "金安 A卷・第6次練習", "pord": 5, "ctx": "", "fig": "", "q": "真相只有一個，柯南在破案時，會透過阿笠博士發明的領結道具讓自己變成毛利小五郎的聲音進行推理，這個道具設計的原理主要是改變聲音的什麼？", "o": ["速率", "頻率", "波形", "響度"], "a": 2, "e": "要變成另一個人的聲音，就是讓聲音的「音色」一樣 → 改變波形。\n只改頻率只會變高或變低，不會像另一個人。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-59", "no": "59", "c": "k6", "src": "金安 A卷 第6次練習", "st": "考卷", "pk": "ja-6", "pname": "金安 A卷・第6次練習", "pord": 5, "ctx": "", "fig": "", "q": "2022 年的市長選舉，某候選人為了造勢，找來舞獅團，一時間鑼鼓喧天，熱鬧非凡。下列有關聲音的說法，何者正確？", "o": ["鑼聲、鼓聲都是由鑼、鼓振動發聲的", "鑼聲、鼓聲是透過空氣分開出來的", "鑼聲、鼓聲響徹雲霄是因為它們的音調高", "在空氣中，鑼聲的傳播速率比鼓聲的傳播速率快"], "a": 0, "e": "鑼聲、鼓聲都是鑼面、鼓面振動產生的，(A) 正確。\n響徹雲霄是因為響度大（振幅大），不是音調高，(C) 錯。\n同在空氣中，各種聲音的傳播速率都一樣，(D) 錯。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-60", "no": "60", "c": "k9", "src": "金安 A卷 第6次練習", "st": "考卷", "pk": "ja-6", "pname": "金安 A卷・第6次練習", "pord": 5, "ctx": "", "fig": "", "q": "通常小學音樂課所學的樂器皆為高音直笛，而國中則教導中音笛。由文章可推測，高音直笛的長度與中音直笛長度的比較，下列何者正確？", "o": ["中音>高音", "中音=高音", "中音<高音", "資料不足，無法確認"], "a": 0, "e": "中音笛的音比高音笛低 → 頻率較低。\n管樂器振動的是管內空氣柱，空氣柱愈長，音調愈低 → 中音笛比較長：中音＞高音。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-61", "no": "61", "c": "k7", "src": "金安 A卷 第6次練習", "st": "考卷", "pk": "ja-6", "pname": "金安 A卷・第6次練習", "pord": 5, "ctx": "", "fig": "", "q": "若同時以中、高音笛與烏克麗麗演奏，則下列敘述何者正確？", "o": ["高音笛的聲音傳得最遠", "烏克麗麗的聲音最大聲", "中音笛聲音最微弱", "三者傳遞速率一樣快"], "a": 3, "e": "在同一空氣中，各種樂器的聲音傳播速率都一樣快，(D) 正確。\n傳得遠不遠、大不大聲要看振幅（響度），和音調高低、樂器種類無關，題目沒有給響度資訊。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-62", "no": "62", "c": "k9", "src": "金安 A卷 第6次練習", "st": "考卷", "pk": "ja-6", "pname": "金安 A卷・第6次練習", "pord": 5, "ctx": "", "fig": "", "q": "若將烏克麗麗的四條弦調整至材質、鬆緊、長度均相同，而粗細如右圖所示，則頻率大小應為何？", "o": ["A>B>C>D", "B>A>D>C", "D>C>B>A", "A=B=C=D"], "a": 0, "e": "材質、鬆緊、長度都相同，只差粗細：愈細的弦振動愈快、頻率愈高。\nA 最細、D 最粗 → 頻率 A＞B＞C＞D。", "h": [], "rep": true, "img": "s3-q62", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-63", "no": "63", "c": "k9", "src": "金安 A卷 第6次練習", "st": "考卷", "pk": "ja-6", "pname": "金安 A卷・第6次練習", "pord": 5, "ctx": "", "fig": "", "q": "龍人家中私藏的百寶箱安裝有高科技聲控鎖，用右圖的四個高腳杯，以嘴唇貼著杯口吹氣，可得四個音調來解鎖。若解除鎖定的音調為 Mi、Re、Sol、Fa，則她必須依照右上圖中高腳杯的什麼順序來吹氣，才能解鎖呢？（附註：一般八音階為 Do、Re、Mi、Fa、Sol、La、Si、Do）", "o": ["cbda", "bacd", "cabd", "badc"], "a": 3, "e": "用嘴「吹」杯口時，振動的是杯內空氣柱：水愈少 → 空氣柱愈長 → 音調愈低。\na 水最少（音最低）→ d 水最多（音最高），依序對應 Re、Mi、Fa、Sol：a＝Re、b＝Mi、c＝Fa、d＝Sol。\n要吹 Mi、Re、Sol、Fa → b、a、d、c。\n★ 吹：空氣柱振動，水多音高；敲：水和杯振動，水少音高。", "h": [], "rep": false, "img": "s3-q63", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-64", "no": "64", "c": "k11", "src": "金安 A卷 第6次練習", "st": "考卷", "pk": "ja-6", "pname": "金安 A卷・第6次練習", "pord": 5, "ctx": "", "fig": "", "q": "右表為兩種動物所能聽見聲音的頻率範圍。在空氣溫度為 15 °C、聲波波速為 34000 cm/s 的環境下，若發出波長為 1000 cm，且音量足夠大的聲波，則參閱表中的資訊，下列有關此兩種動物是否能聽到此聲波的敘述何者最合理？", "o": ["兩種動物都聽得到此聲波", "兩種動物都聽不到此聲波", "此聲波大象聽得到，而兔子聽不到", "此聲波兔子聽得到，而大象聽不到"], "a": 2, "e": "先算頻率：f＝v÷λ＝34000÷1000＝34 Hz。\n大象聽 16～12000 Hz，34 Hz 在範圍內 → 聽得到；兔子聽 360～42000 Hz，34 Hz 太低 → 聽不到。", "h": ["題目給波速和波長，先算出頻率。", "把頻率和兩種動物的聽覺範圍比一比。"], "rep": true, "img": "s3-q64", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-65", "no": "65", "c": "k8", "src": "金安 A卷 第6次練習", "st": "考卷", "pk": "ja-6", "pname": "金安 A卷・第6次練習", "pord": 5, "ctx": "", "fig": "", "q": "右圖為同一時間內甲、乙、丙、丁四支音叉所發出聲波的波形，下列何者的音調相同而振幅不同？", "o": ["甲、乙", "乙、丙", "丙、丁", "甲、丁"], "a": 3, "e": "音調相同 → 同一時間內波數相同；振幅不同 → 波形高度不同。\n甲、丁的波數一樣，甲比丁高 → 選甲、丁。", "h": [], "rep": false, "img": "s3-q65", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-66", "no": "66", "c": "k8", "src": "金安 A卷 第6次練習", "st": "考卷", "pk": "ja-6", "pname": "金安 A卷・第6次練習", "pord": 5, "ctx": "", "fig": "", "q": "承上題，下列何者的音量相同而週期不同？", "o": ["甲、乙", "乙、丙", "丙、丁", "甲、丁"], "a": 1, "e": "音量（響度）相同 → 振幅相同；週期不同 → 波的疏密不同。\n乙、丙的高度一樣，但乙比丙密得多 → 選乙、丙。", "h": [], "rep": false, "img": "s3-q66", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-67", "no": "67", "c": "k8", "src": "金安 A卷 第6次練習", "st": "考卷", "pk": "ja-6", "pname": "金安 A卷・第6次練習", "pord": 5, "ctx": "", "fig": "", "q": "「弦樂四重奏」是由 2 把小提琴、1 把中提琴、1 把大提琴所組成的合奏。演奏到主旋律時，四把琴都演奏相同音調的音階，但指揮仍能分辨每一把琴的聲音而加以指揮，其原因為下列何者？", "o": ["四者音量相同", "四者音色相同", "四者頻率相同", "四者音色不同"], "a": 3, "e": "四把琴演奏同一個音（頻率相同），指揮還能分辨，是因為不同樂器的波形不同 → 音色不同。", "h": [], "rep": false, "img": "s3-q67", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-68", "no": "68", "c": "k7", "src": "金安 A卷 第6次練習", "st": "考卷", "pk": "ja-6", "pname": "金安 A卷・第6次練習", "pord": 5, "ctx": "", "fig": "", "q": "承上題，演奏到某一長音時，小提琴的旋律是快速而明快，中提琴的旋律是強大而穩定，大提琴的旋律是低沉而緩慢，何者的聲速最快？", "o": ["小提琴", "中提琴", "大提琴", "一樣快"], "a": 3, "e": "聲速只和介質（空氣）有關，和演奏快慢、強弱、高低都無關 → 一樣快。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-69", "no": "69", "c": "k9", "src": "翰林 C卷 第9回 第 1 題", "st": "考卷", "pk": "hl-C-9", "pname": "翰林 C卷・第9回（第3～4章）", "pord": 4, "ctx": "", "fig": "", "q": "右圖為小朋友常玩的敲擊樂器，該樂器是由長短不一的鋼管所組合而成，其音階由低至高的排列順序為何？", "o": ["由左至右", "由右至左", "依敲擊的力道而定", "此樂器無音調高低的差別"], "a": 0, "e": "鋼管愈長，振動愈慢，音調愈低。圖中左邊鋼管最長、右邊最短 → 音階由左（低）至右（高）。\n敲的力道只影響響度。", "h": [], "rep": false, "img": "s3-q69", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-70", "no": "70", "c": "k11", "src": "翰林 C卷 第9回 第 2 題", "st": "考卷", "pk": "hl-C-9", "pname": "翰林 C卷・第9回（第3～4章）", "pord": 4, "ctx": "", "fig": "", "q": "有些聲音我們稱之為超聲波，其特點為何？", "o": ["響度較大", "振幅較大", "波形較複雜", "頻率較高"], "a": 3, "e": "超聲波是頻率高於 20000 Hz 的聲波，特點是頻率較高（人耳聽不到）。\n和響度、振幅、波形無關。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-71", "no": "71", "c": "k4", "src": "翰林 C卷 第9回 第 3 題", "st": "考卷", "pk": "hl-C-9", "pname": "翰林 C卷・第9回（第3～4章）", "pord": 4, "ctx": "", "fig": "", "q": "右圖為一水波波形示意圖，則 AB 之間相當於幾個波長？", "o": ["1", "1.5", "2", "3"], "a": 1, "e": "一個波長＝一個波峰＋一個波谷。A 到 B 之間有 1 個完整的波再加半個波 → 1.5 個波長。", "h": [], "rep": false, "img": "s3-q71", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-72", "no": "72", "c": "k7", "src": "翰林 C卷 第9回 第 4 題", "st": "考卷", "pk": "hl-C-9", "pname": "翰林 C卷・第9回（第3～4章）", "pord": 4, "ctx": "", "fig": "", "q": "甲、乙、丙三個人在教室內說話，其講話特色分別為甲說得很快，乙聲音很尖銳，丙很用力地講，則誰的聲速最大？", "o": ["甲", "乙", "丙", "都相等"], "a": 3, "e": "聲速只由介質決定。說得快、聲音尖、用力講分別影響說話節奏、音調、響度，都不影響聲速 → 都相等。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-73", "no": "73", "c": "k9", "src": "翰林 C卷 第9回 第 5 題", "st": "考卷", "pk": "hl-C-9", "pname": "翰林 C卷・第9回（第3～4章）", "pord": 4, "ctx": "", "fig": "", "q": "當琴絃的鬆緊程度和材質都相同時，則下列哪一種絃線的音調最高？", "o": ["長度 50 cm、直徑 2 mm", "長度 50 cm、直徑 1 mm", "長度 80 cm、直徑 2 mm", "長度 80 cm、直徑 1 mm"], "a": 1, "e": "鬆緊、材質相同時，弦愈短、愈細，振動愈快，音調愈高。\n長度 50 cm（短）、直徑 1 mm（細）→ 選 (B)。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-74", "no": "74", "c": "k8", "src": "翰林 C卷 第9回 第 6 題", "st": "考卷", "pk": "hl-C-9", "pname": "翰林 C卷・第9回（第3～4章）", "pord": 4, "ctx": "", "fig": "", "q": "下圖是童謠「小蜜蜂」的歌詞與樂譜，在小萍唱到「大家一齊」這四個字的期間，聲波的音調逐漸升高。此期間聲波音調逐漸升高，主要是因為下列何種變化？", "o": ["聲波的振幅逐漸增加", "聲波的頻率逐漸變低", "小萍聲帶每回振動一次的時間逐漸增加", "小萍聲帶每秒來回振動的次數逐漸增加"], "a": 3, "e": "音調升高 → 頻率變高 → 聲帶每秒振動次數增加（每振動一次的時間變短）。\n振幅影響的是響度，不是音調。", "h": [], "rep": false, "img": "s3-q74", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-75", "no": "75", "c": "k6", "src": "翰林 C卷 第9回 第 7 題", "st": "考卷", "pk": "hl-C-9", "pname": "翰林 C卷・第9回（第3～4章）", "pord": 4, "ctx": "", "fig": "", "q": "在近乎真空的太空中，有三艘太空船甲、乙、丙，其中丙太空船與甲、乙太空船相距不遠且未互相接觸，若甲、乙太空船意外相撞但未發生爆炸，試判斷丙太空船中的太空人是否能聽見由甲、乙相撞處直接傳來的聲響，及其主要的原因為何？", "o": ["幾乎不能聽見，因聲音需要經由介質來傳播", "幾乎不能聽見，因聲音在太空中的傳播速率太慢", "能清楚聽見，因聲音可經由障礙物反射來傳播", "能清楚聽見，因聲音可能由熱輻射的方式來傳播"], "a": 0, "e": "太空近乎真空，沒有介質可以傳聲，所以丙幾乎聽不到撞擊聲。\n★ 聲音一定要靠介質傳播。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-76", "no": "76", "c": "k5", "src": "翰林 C卷 第9回 第 8 題", "st": "考卷", "pk": "hl-C-9", "pname": "翰林 C卷・第9回（第3～4章）", "pord": 4, "ctx": "", "fig": "", "q": "有一水波的波形如右圖所示，已知波速為 80 公分／秒，則水波的頻率為多少赫？", "o": ["0.5", "1", "2", "4"], "a": 2, "e": "由圖：相鄰兩波峰相距 40 公分 → 波長 40 公分。\nf＝v÷λ＝80÷40＝2 赫。", "h": ["從圖上找出相鄰兩波峰的距離（波長）。", "f＝v÷λ。"], "rep": false, "img": "s3-q76", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-77", "no": "77", "c": "k8", "src": "翰林 C卷 第9回 第 9 題", "st": "考卷", "pk": "hl-C-9", "pname": "翰林 C卷・第9回（第3～4章）", "pord": 4, "ctx": "", "fig": "", "q": "關於聲音的敘述，下列何者正確？", "o": ["聲音振動的頻率愈高，聲音可以傳得愈遠", "聲音的音調，以分貝為測量的單位", "聲音的響度愈大，聲速愈快", "我們能分辨不同樂器的聲音，是由於其音色不同"], "a": 3, "e": "傳得遠不遠由響度（振幅）決定，不是頻率，(A) 錯。\n分貝是響度單位，音調的單位是赫茲，(B) 錯。\n聲速由介質決定，和響度無關，(C) 錯。\n分辨樂器靠音色，(D) 正確。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-78", "no": "78", "c": "k6", "src": "金安 A卷 第9次練習 第 12 題", "st": "考卷", "pk": "ja-9", "pname": "金安 A卷・第9次練習", "pord": 6, "ctx": "", "fig": "", "q": "大雄利用多啦A夢的任意門跑到月球上，回頭看了一眼前地球，請問下列敘述何者最合理？", "o": ["可以看到美麗的地球，是因為地球本身會發光", "若用無窮遠擴音器對地球大喊「哈囉」，地球上的人可以聽到", "可以利用聲納來探測與地球之間的距離", "太空中靜悄悄的，是因為真空無法傳播聲音"], "a": 3, "e": "地球本身不會發光，是反射太陽光，(A) 錯。\n月球和地球之間是真空，聲音（包括聲納的超聲波）都傳不過去，(B)(C) 錯。\n太空靜悄悄是因為真空無法傳聲，(D) 正確。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-79", "no": "79", "c": "k9", "src": "金安 A卷 第9次練習 第 13 題", "st": "考卷", "pk": "ja-9", "pname": "金安 A卷・第9次練習", "pord": 6, "ctx": "", "fig": "", "q": "阿金為了要打開一個音調為 Re（587 Hz）、Sol（784 Hz）、Mi（659 Hz）、Si（988 Hz）的音樂鎖，他取得了四個大小相同的杯子，倒入四杯不等量的水，如上圖所示，並以玻璃棒輕敲這四個杯子，而得到這四個音調，最後終於將鎖打開，請問他必須按照什麼順序對杯子輕敲？", "o": ["acbd", "dbca", "cbda", "abcd"], "a": 1, "e": "用玻璃棒「敲」杯子時，振動的是杯子和水：水愈少，音調愈高。\n圖中 a 水最少（音最高）→ d 水最多（音最低）。\n頻率由低到高：Re 587＜Mi 659＜Sol 784＜Si 988 → d＝Re、c＝Mi、b＝Sol、a＝Si。\n要敲 Re、Sol、Mi、Si → d、b、c、a。\n★ 敲：水少音高；吹：水多音高。", "h": [], "rep": false, "img": "s3-q79", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-80", "no": "80", "c": "k11", "src": "金安 A卷 第9次練習 第 16 題", "st": "考卷", "pk": "ja-9", "pname": "金安 A卷・第9次練習", "pord": 6, "ctx": "", "fig": "", "q": "海洋公園的海豚訓練師常以特殊的哨音下達指令，但人耳卻聽不見，試根據右表數據判斷，該哨音頻率可能為多少？", "o": ["10 Hz", "1000 Hz", "30000 Hz", "300000 Hz"], "a": 2, "e": "人耳聽 20～20000 Hz，海豚聽 2000～100000 Hz。\n人聽不到但海豚聽得到 → 要大於 20000 Hz 且不超過 100000 Hz → 30000 Hz。", "h": [], "rep": true, "img": "s3-q80", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-81", "no": "81", "c": "k1", "src": "講義 p.79 隨堂練習 1 第 1 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列物質受到干擾後，哪一種不是波的現象？", "o": ["舞者揮動的彩帶", "風吹樹葉飄落", "搖動繩子", "擾動彈簧"], "a": 1, "e": "波是擾動在介質中傳遞，介質只在原處振動。\n樹葉被風吹落，是樹葉整個移動到別處，不是波動。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-82", "no": "82", "c": "k1", "src": "講義 p.79 隨堂練習 1 第 2 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列何者對於波的介質描述是錯誤的？", "o": ["水波：介質為水", "彈簧波：介質為彈簧", "繩波：介質為繩子", "聲波：介質為聲音"], "a": 3, "e": "聲波的介質是空氣（或其他物質），不是「聲音」。聲音本身就是波。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-83", "no": "83", "c": "k1", "src": "講義 p.79 隨堂練習 1 第 3 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "某天靜香經過小池塘發現水中央有一顆小球，如果要撿拾這顆球，下列方式何者可以做到？", "o": ["在岸邊拍打水面產生波動", "將石頭丟到水中央使水產生波動", "找一根夠長的竹竿將球撥回岸邊", "以上三個方法皆可行"], "a": 2, "e": "波只傳遞能量，水面的球只會在原處上下振動，不會被水波帶到岸邊。\n要撿球只能直接用竹竿撥回來。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-84", "no": "84", "c": "k1", "src": "講義 p.79 隨堂練習 1 第 4 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "若在水面上放一片保麗龍，當水波通過時會發現保麗龍僅在原處上下振動，其表示的意義為何？", "o": ["水波可以傳遞能量，也可以傳遞介質", "水波只能傳遞能量，不能傳遞介質", "水波只能傳遞介質，不能傳遞能量", "水波不能傳遞能量，也不能傳遞介質"], "a": 1, "e": "保麗龍只在原處上下振動、沒有跟著前進 → 水波只傳遞能量，不傳遞介質。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-85", "no": "85", "c": "k2", "src": "講義 p.79 隨堂練習 1 第 5 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列有關力學波的敘述，何者錯誤？", "o": ["可以藉由玻璃傳遞", "在真空中仍可傳播", "可以藉由空氣傳播", "一定要依靠介質才能傳播"], "a": 1, "e": "力學波（如聲波、水波）一定要靠介質傳播，在真空中無法傳播 → (B) 錯誤，選它。\n玻璃、空氣都是介質，可以傳遞。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-86", "no": "86", "c": "k3", "src": "講義 p.79 隨堂練習 1 第 6 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "關於橫波和縱波的敘述，下列何者錯誤？", "o": ["介質振動方向和波行進方向垂直的稱為橫波", "介質振動方向和波行進方向平行的稱為縱波", "一種介質只能產生其中一種波，不可能兩種波都會產生", "不論是橫波或縱波，物質都不會跟著移動"], "a": 2, "e": "同一種介質可以產生兩種波：例如彈簧左右推拉是縱波、上下甩動是橫波 → (C) 錯誤，選它。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-87", "no": "87", "c": "k5", "src": "講義 p.79 隨堂練習 1 第 7 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "右圖甲為一繩波上的瞬間波形穩定向右傳送，經 0.4 秒後其波形如圖乙所示，此繩波之波速為多少？", "o": ["25 cm / s", "50 cm / s", "100 cm / s", "125 cm / s"], "a": 3, "e": "經過 0.4 秒，波形向右移動了 50 cm。\nv＝距離÷時間＝50÷0.4＝125 cm/s。", "h": ["比較甲、乙兩圖，波形移動了多遠？", "v＝L÷t。"], "rep": false, "img": "s3-q87", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-88", "no": "88", "c": "k4", "src": "講義 p.82 隨堂練習 2 第 1 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "右圖的彈簧波為連續週期波，則下列關於此彈簧波的敘述何者錯誤？", "o": ["振幅為 5 cm", "波長為 10 cm", "a 點為疏部，c 點為密部", "ac 點長度為 0.5λ"], "a": 0, "e": "彈簧疏密波只看得出疏密，看不出振幅 → (A)「振幅為 5 cm」錯誤，選它。\n20 cm 內有 2 個完整疏密 → 波長 10 cm；a 為疏部、c 為密部，相鄰疏部到密部是半個波長（0.5λ）。", "h": [], "rep": false, "img": "s3-q88", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-89", "no": "89", "c": "k5", "src": "講義 p.82 隨堂練習 2 第 2 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "右圖為相同時間內在同一均勻介質傳播的甲、乙兩個波的波形，請問下列敘述何者正確？", "o": ["甲、乙兩波的波長比為 1：1", "甲、乙兩波的週期比為 1：2", "甲、乙兩波的振幅比為 1：2", "甲、乙兩波的頻率比為 1：2"], "a": 3, "e": "同一時間、同一介質 → 波速相同。\n18 cm 內：甲 1.5 個波（λ＝12 cm），乙 3 個波（λ＝6 cm）→ 波長比 2：1。\n波速相同，週期和波長成正比 → 週期比 2：1；頻率比 1：2 → (D) 正確。\n甲的振幅比乙大，(C) 錯。", "h": ["數一數 18 cm 內甲、乙各有幾個波。", "同介質波速相同，頻率和波長成反比。"], "rep": false, "img": "s3-q89", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-90", "no": "90", "c": "k1", "src": "講義 p.84 基礎題 第 7 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "一彈簧波如右圖所示，則下列敘述何者錯誤？", "o": ["a、b 兩點間波形疏密相同又稱為疏密波", "當波向前傳播時，介質也隨波向前移動", "能量沿波前進的方向傳送", "此波為縱波"], "a": 1, "e": "縱波傳播時，介質只在原處前後（左右）振動，不會跟著波前進 → (B) 錯誤，選它。\n波傳遞的是能量。", "h": [], "rep": false, "img": "s3-q90", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-91", "no": "91", "c": "k3", "src": "講義 p.84 基礎題 第 8 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "阿翰觀察琳琳在跳彩帶舞時，彩帶的振動方向是南北向，那麼彩帶上波的行進方向不可能是哪個方向？", "o": ["向下", "向東", "向上", "向南"], "a": 3, "e": "彩帶的波是橫波：振動方向和行進方向垂直。\n振動方向是南北向 → 行進方向可以是東西或上下，但不可能是「向南」。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-92", "no": "92", "c": "k4", "src": "講義 p.84 基礎題 第 9 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "如右圖，若此繩波從左到右的總長度為 18 公分，振幅為 5 公分，則此繩波波長為多少公分？", "o": ["4", "8", "9", "16"], "a": 1, "e": "由圖：18 公分內有 2 又 1/4 個波（2.25 個波）。\n波長＝18÷2.25＝8 公分。振幅 5 公分是干擾條件。", "h": ["數一數 18 公分內有幾個完整的波（可以是小數）。"], "rep": false, "img": "s3-q92", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-93", "no": "93", "c": "k4", "src": "講義 p.84 基礎題 第 10 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "一連續週期波通過介質中某一點時，該點作往復運動的位置座標(y)與時間(t)關係圖如右圖所示，其中介質振動的方向與波行進的方向垂直。下列何者正確？", "o": ["振幅為 16 公分", "週期為 0.8 秒", "波長為 8 公分", "頻率為 5 赫"], "a": 3, "e": "這是位置－時間圖：最高 8 公分 → 振幅 8 公分，(A) 錯。\n兩波峰相隔 0.2 秒 → 週期 0.2 秒，(B) 錯；頻率＝1÷0.2＝5 赫，(D) 正確。\n時間圖看不出波長，(C) 錯。", "h": [], "rep": false, "img": "s3-q93", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-94", "no": "94", "c": "k4", "src": "講義 p.84 基礎題 第 11 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "振動時繩子往復振動一次所需時間稱為週期，如右圖，振動一次介質的路徑應為下列何者？", "o": ["A→B→C→D→E", "B→F→G→F→B", "A→F→C→E", "A→B→C→G→A"], "a": 1, "e": "繩上每一點只在原處上下振動。振動一次：B（最高）→F（平衡）→G（最低）→F→B。\n★ 振動一次＝走 4 個振幅。", "h": [], "rep": false, "img": "s3-q94", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-95", "no": "95", "c": "k1", "src": "講義 p.84 基礎題 第 12 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "將繩的一端固定在 O 點上，用手持另一端 A 點，則將繩由 A 點先向 C 點移動，再向 B 點移動，然後回到 A 點，共在 2 秒內完成，若手持續移動繩子，則繩波在第 4 秒末所呈現的波形為何者？", "o": ["圖A波形", "圖B波形", "圖C波形", "圖D波形"], "a": 3, "e": "手完成一次「下→上→回原位」花 2 秒 → 週期 2 秒。\n第 4 秒末共振動 2 次 → 繩上有 2 個完整的波。\n手先往下（C 點）動，最先出發的是波谷 → 波谷跑在最前面（最靠近 O 的右側）→ 選 (D)。", "h": ["週期是多少？4 秒內產生幾個波？", "手先往哪個方向動，最前端的波就是波峰還是波谷。"], "rep": false, "img": "s3-q95", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-96", "no": "96", "c": "k4", "src": "講義 p.84 基礎題 第 13 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "承上題，當手持續繩 A 點作上下振動時，產生的連續波的波長為 L 公分，若 X、Y 兩點間的距離為 0.5L 公分，則當 X 點在波峰時，Y 點在哪一點上？", "o": ["波峰上", "平衡線上", "波谷上", "視波速而定"], "a": 2, "e": "兩點相距半個波長（0.5L）時，振動狀態剛好相反。\nX 在波峰 → Y 在波谷。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-97", "no": "97", "c": "k1", "src": "講義 p.84 基礎題 第 14 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "右圖為一個連續性週期波，請問 a、b 兩點的瞬間運動方向應為何者？", "o": ["a、b 均向右", "a、b 均向上", "a 向下、b 向下", "a 向上、b 向下"], "a": 3, "e": "波向右前進時：波峰「前面」的點往上、「後面」的點往下。\na 在第一個波峰的前方下坡 → 向上；b 在第二個波峰的後方上坡 → 向下。", "h": [], "rep": false, "img": "s3-q97", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-98", "no": "98", "c": "k7", "src": "講義 p.92 隨堂練習 3 第 1 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "關於聲音在各種介質中傳播速率的快慢，由快至慢依序應為何？", "o": ["空氣>木頭>水", "木頭>水>空氣", "空氣>水>木頭", "水>空氣>木頭"], "a": 1, "e": "聲速：固體＞液體＞氣體 → 木頭＞水＞空氣。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-99", "no": "99", "c": "k7", "src": "講義 p.92 隨堂練習 3 第 2 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "如右圖，采靜和她的朋友隔河對唱情歌，河寬 68 公尺，她的聲音傳到對方約需多少時間？（當時無風，氣溫 15 °C）", "o": ["0.002 秒", "0.02 秒", "0.2 秒", "2.0 秒"], "a": 2, "e": "15 °C 聲速 v＝331＋0.6×15＝340 m/s。\nt＝68÷340＝0.2 秒。", "h": ["先用 v＝331＋0.6T 算聲速。", "時間＝距離÷速度。"], "rep": false, "img": "s3-q99", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-100", "no": "100", "c": "k7", "src": "講義 p.92 隨堂練習 3 第 3 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "大雄、胖虎和靜香一起在司令臺上表演，大雄大聲唱歌、胖虎打鈴鼓、靜香彈吉他伴奏，若他們同時發出聲音，請問哪個聲音會先傳到操場的最後面？", "o": ["歌聲", "鈴鼓聲", "吉他聲", "三個聲音一起到"], "a": 3, "e": "同在空氣中，所有聲音的速率都相同，三個聲音一起到。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-101", "no": "101", "c": "k6", "src": "講義 p.92 試題搶先做 第 1 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "實驗室裡，某生取一音叉，並將音叉直立桌上，如右圖。再用小槌敲擊後聽到聲音，若用手緊握音叉兩股，則音叉聲音變化如何？", "o": ["不變", "減小", "消失", "時大時小"], "a": 2, "e": "聲音是音叉振動產生的。手緊握音叉，振動停止 → 聲音消失。", "h": [], "rep": false, "img": "s3-q101", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-102", "no": "102", "c": "k6", "src": "講義 p.92 試題搶先做 第 2 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "承上題，將發音的音叉接觸水面，水面會濺起水花，可知音叉發生此現象的原因為何？", "o": ["有重力觸及水面", "對水有吸附力", "對水有排斥力", "快速振動觸及水面"], "a": 3, "e": "發聲的音叉正在快速振動，碰到水面就把水濺起來 → 證明發聲體在振動。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-103", "no": "103", "c": "k6", "src": "講義 p.93 試題搶先做 第 3 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列何種現象可證明物體發出聲音，是由於物體的振動？", "o": ["鼓面上的米粒會因鼓被敲打而發出聲音時，米粒隨著鼓面的振動而上下跳動", "撥動橡皮筋時，橡皮筋來回振動而發聲", "蚊子展開翅膀飛翔時所發出的聲音", "以上皆是"], "a": 3, "e": "米粒跳動、橡皮筋來回振動、蚊子翅膀拍動，都說明發聲體在振動 → 以上皆是。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-104", "no": "104", "c": "k6", "src": "講義 p.93 試題搶先做 第 4 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "有關聲音產生的敘述，下列何者錯誤？", "o": ["雷聲是閃電急速振動產生的", "流水聲是水快速振動產生的", "歌唱聲是聲帶振動而產生的", "吉他聲是弦線振動而產生的"], "a": 0, "e": "雷聲是閃電使周圍空氣急速受熱膨脹、空氣快速振動產生的，不是閃電本身振動 → (A) 錯誤。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-105", "no": "105", "c": "k6", "src": "講義 p.93 試題搶先做 第 5 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "撥動一條琴弦，使琴發出聲音，我們能聽到聲音的原因為下列何者？", "o": ["琴弦在振動", "琴弦與空氣在振動", "空氣在振動", "琴弦、空氣、耳膜都在振動"], "a": 3, "e": "琴弦振動 → 帶動空氣振動（傳播）→ 使耳膜振動 → 我們聽到聲音。三者都在振動。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-106", "no": "106", "c": "k6", "src": "講義 p.93 試題搶先做 第 6 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列何者可以證明液體可以傳聲？", "o": ["水上芭蕾舞者潛入水中，仍可隨音樂起舞", "鯨魚發出聲波與同伴溝通訊息", "放入水中的鬧鐘，鈴聲響時仍可聽見其鈴聲", "以上皆可"], "a": 3, "e": "(A)(B)(C) 都是聲音在水中傳播的例子 → 以上皆可。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-107", "no": "107", "c": "k6", "src": "講義 p.93 試題搶先做 第 7 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列敘述何者不能證明聲音可利用固體傳播？", "o": ["太空人以無線電跟地球上的人通話", "耳朵貼於桌面上，可聽到遠端鬧鐘的滴答聲", "將長鐵條的一端附於用發條帶動齒輪的手錶上，附耳在另一端能聽到滴答聲", "把耳朵貼在鐵軌上，可聽到遠處火車在鐵軌上行駛的聲音"], "a": 0, "e": "無線電是電磁波，不需要介質，和固體傳聲無關 → (A) 不能證明。\n(B)(C)(D) 分別透過桌面、鐵條、鐵軌（固體）傳聲。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-108", "no": "108", "c": "k6", "src": "講義 p.93 試題搶先做 第 8 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "如右圖，一密閉玻璃鐘罩內的空氣無法外漏，但置於玻璃鐘罩內的鬧鐘響聲，在玻璃鐘罩外仍可以聽見，由此實驗觀察可以說明，傳遞聲波時，下列何者正確？", "o": ["空氣分子會隨聲波向前移動", "空氣分子會在容器內做來回的反射", "玻璃也可以傳遞聲音", "玻璃傳聲的速率比空氣快"], "a": 2, "e": "罩內空氣出不來，但罩外仍聽得到 → 聲音透過玻璃傳出來 → 玻璃（固體）也能傳聲。\n空氣分子只在原處振動，不會隨波前進。", "h": [], "rep": false, "img": "s3-q108", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-109", "no": "109", "c": "k6", "src": "講義 p.93 試題搶先做 第 9 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "在近乎真空的太空中，有三艘太空船甲、乙、丙，其中丙太空船與甲、乙太空船相距不遠且未互相接觸，若甲、乙太空船意外相撞但未發生爆炸，試判斷丙太空船中的太空人是否能聽見由甲、乙相撞處直接傳來的聲響，及其主要的原因為何？", "o": ["幾乎不能聽見，因聲音需要經由介質來傳播", "幾乎不能聽見，因聲音在太空中的傳播速率太慢", "能清楚聽見，因聲音可經由障礙物反射來傳遞", "能清楚聽見，因聲音可經由波的方式來傳播"], "a": 0, "e": "太空近乎真空，沒有介質傳聲 → 幾乎聽不到。聲音需要介質才能傳播。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-110", "no": "110", "c": "k7", "src": "講義 p.94 基礎題 第 10 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "小夫在觀看煙火時，看到亮光後，過了 2 秒鐘才聽到爆炸聲。已知聲音和光在空氣中的傳播速率分別為 340 公尺／秒和 30 萬公里／秒，則煙火爆炸的地點與小夫的距離約為多少？", "o": ["170 公尺", "680 公尺", "15 萬公里", "60 萬公里"], "a": 1, "e": "光速極快，傳播時間可忽略。距離＝340×2＝680 公尺。", "h": ["光的傳播時間要不要算？", "距離＝聲速×時間。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-111", "no": "111", "c": "k6", "src": "講義 p.94 基礎題 第 11 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "若 X 星球距地球 1.5 × 10⁸ km，假設 X 星球發生大爆炸，而當時聲音在空氣中傳播速率為 300 m / s，則爆炸聲要經過多少時間才會傳到地球？", "o": ["5 × 10⁵ 秒", "5 × 10⁶ 秒", "5 × 10⁷ 秒", "聽不到"], "a": 3, "e": "X 星球和地球之間是真空，聲音無法傳播 → 聽不到。\n數字都是陷阱，真空根本傳不了聲音。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-112", "no": "112", "c": "k7", "src": "講義 p.94 基礎題 第 12 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "學校運動會，小明參加百米短跑項目，一位站在終點計時的烏龍計時員竟然是聽到槍響後，才按下碼錶，若當時無風，氣溫 25 °C，聲速 346 公尺／秒，則小明的成績應如何更正才正確？", "o": ["加上 0.29 秒", "扣掉 0.29 秒", "加上 0.6 秒", "扣掉 0.6 秒"], "a": 0, "e": "計時員應該「看到槍煙」就按錶，卻等聲音跑 100 公尺才按，少計了聲音傳播的時間。\nt＝100÷346≈0.29 秒 → 成績要加上 0.29 秒。", "h": ["聲音從起點傳到終點要多久？", "晚按碼錶，記錄的時間是變長還是變短？"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-113", "no": "113", "c": "k7", "src": "講義 p.94 基礎題 第 13 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "靜止在海面上的甲船發出聲波訊號，訊號同時由空氣及海水以直線傳至同樣靜止在海面上的乙船，如右圖所示。假設當時無風，且海面平靜，在空氣中的聲速為 340 m / s，在海水中的聲速為 1700 m / s，則乙船先後接收到上述兩個聲波訊號的時間差最接近下列何者？", "o": ["0.3 秒", "0.5 秒", "1.6 秒", "2 秒"], "a": 2, "e": "空氣中：680÷340＝2 秒；海水中：680÷1700＝0.4 秒。\n時間差＝2－0.4＝1.6 秒。", "h": ["分別算兩條路徑所需時間。", "相減就是時間差。"], "rep": false, "img": "s3-q113", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-114", "no": "114", "c": "k5", "src": "講義 p.94 基礎題 第 14 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "有一聲源發出之聲音由空氣傳入水中，則下列敘述何者正確？", "o": ["聲音傳遞速率不變", "聲波波長變小", "聲波頻率保持不變", "聲波振幅變大"], "a": 2, "e": "頻率由聲源決定，進入不同介質也不變 → (C) 正確。\n進入水中聲速變快，波長變長，(A)(B) 錯。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-115", "no": "115", "c": "k7", "src": "講義 p.94 基礎題 第 15 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "聲音在空氣中傳播時，下列敘述何者正確？(甲)聲速與發音體的振動頻率無關；(乙)發音體的振動幅度愈大，聲速愈快；(丙)溫度愈高，聲速愈快；(丁)聲音傳得愈遠，振幅不變；(戊)聲音在空氣中傳播屬於縱波。", "o": ["甲丙丁戊", "僅甲丙戊", "僅甲丙丁戊", "僅乙丙"], "a": 1, "e": "(甲) 聲速與頻率無關，正確。(乙) 聲速與振幅無關，錯。(丙) 溫度愈高聲速愈快，正確。\n(丁) 傳得愈遠振幅愈小，錯。(戊) 空氣中的聲波是縱波，正確。→ 僅甲丙戊。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-116", "no": "116", "c": "k7", "src": "講義 p.94 基礎題 第 16 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "有關影響聲音傳播快慢的敘述，下列何者正確？", "o": ["聲音愈大，傳得愈快", "聲音愈高，傳得愈快", "說得愈急，傳得愈快", "一般在密度較大的介質，如固體中傳播較快"], "a": 3, "e": "聲速只由介質決定，和音量、音調、說話快慢無關。\n一般在固體中傳得最快 → (D)。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-117", "no": "117", "c": "k8", "src": "講義 p.103 基礎題 第 9 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "通常交談時，男生的聲音較低沉，而女生的聲音較尖銳，這是下列何種不同而導致？", "o": ["振幅", "聲速", "頻率", "響度"], "a": 2, "e": "男生聲帶振動較慢、頻率低 → 低沉；女生頻率高 → 尖銳。差別在頻率。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-118", "no": "118", "c": "k9", "src": "講義 p.103 基礎題 第 10 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "如右圖所示的四個鐵管，其材質及管徑粗細皆相同，但長度為甲>乙>丙>丁，若用鎚子敲打時，下列哪一種情形所發出的聲音音調最高？", "o": ["每秒敲甲 5 次", "每秒敲乙 2 次", "每秒敲丙 3 次", "每秒敲丁 4 次"], "a": 3, "e": "鐵管的音調由鐵管本身決定：愈短頻率愈高，和每秒敲幾次無關。\n丁最短 → 音調最高。", "h": [], "rep": false, "img": "s3-q118", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-119", "no": "119", "c": "k8", "src": "講義 p.103 基礎題 第 11 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "在擊大鼓的表演中，當擊鼓手敲擊大鼓的節奏愈快時，則其產生的鼓聲為何？", "o": ["音調愈高", "音速愈快", "響度愈大", "鼓膜振動的頻率並未改變"], "a": 3, "e": "敲得快慢只是節奏變快，鼓膜本身的振動頻率不變，音調不變。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-120", "no": "120", "c": "k9", "src": "講義 p.103 基礎題 第 12 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "甲、乙、丙、丁是四支不同長度的空心管子，管子的下端皆封閉，上端皆敞開，如右圖所示。假設小明利用這四支管子可以吹出四種不同音調，且為單一頻率的聲音，每支管子「管口至封閉端的距離」皆為其所發出聲波波長的 1/4，則哪一支管子所發出聲音的音調最高？", "o": ["甲管", "乙管", "丙管", "丁管"], "a": 0, "e": "管長＝波長的 1/4 → 管愈短，波長愈短。\n同在空氣中聲速相同，波長愈短頻率愈高 → 最短的甲管音調最高。", "h": [], "rep": false, "img": "s3-q120", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-121", "no": "121", "c": "k9", "src": "講義 p.103 基礎題 第 13 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "喬帥以正確調音過的吉他進行演奏，下列何者正確？", "o": ["同一弦，弦振動的長度愈長，音調愈低", "同一弦，弦振動的幅度愈大，音調愈高", "同一弦，弦振動的長度愈短，音調愈低", "不同弦，弦振動的長度相同，粗弦音調較高"], "a": 0, "e": "同一條弦：振動的長度愈長，振動愈慢，音調愈低 → (A) 正確，(C) 相反。\n振動幅度大只會更大聲，不會改變音調，(B) 錯。\n不同弦長度相同時，細弦音調較高，(D) 錯。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-122", "no": "122", "c": "k8", "src": "講義 p.103 基礎題 第 14 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "朝會時我們不用看就能分辨出學務主任與生教組長的聲音，主要是因為兩種聲音有何不同？", "o": ["分貝數不同", "波形不同", "頻率不同", "表達方式不同"], "a": 1, "e": "每個人聲帶構造不同，發出的聲音波形不同 → 音色不同，所以能聞聲辨人。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-123", "no": "123", "c": "k8", "src": "講義 p.103 基礎題 第 15 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "技安以正確的姿勢敲擊木琴，下列何者是他比較能控制的要素？", "o": ["音調與響度", "音色與音調", "響度與音色", "音速與音色"], "a": 0, "e": "敲不同長短的琴鍵可以改變音調，敲的輕重可以改變響度。\n音色由木琴本身的材質決定、無法改變；音速由空氣決定。→ 音調與響度。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-124", "no": "124", "c": "k8", "src": "講義 p.103 基礎題 第 16 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列何者不是樂音與噪音的區別？", "o": ["一般樂音的聲波較有規律性而噪音則無", "聽起來令人感覺舒服的聲音稱為樂音，反之則是噪音", "聲波的頻率過高，超過了人耳所能承受的範圍稱為噪音，反之則是樂音", "噪音會使人心情報燥、易怒，嚴重者甚至失去聽覺，樂音則不會"], "a": 2, "e": "頻率超過人耳範圍（20000 Hz 以上）是超聲波，人根本聽不到，不叫噪音 → (C) 不是區別，選它。\n樂音規律、悅耳；噪音不規律、令人不舒服、會傷害聽力。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-125", "no": "125", "c": "k8", "src": "講義 p.103 基礎題 第 17 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列關於噪音的描述，哪兩項是正確的？(甲) dB是響度的單位；(乙)一般 dB 數字愈大，給人的感覺愈不舒服；(丙)婚喪喜慶是重要的活動，若事先申請，就可以不考慮噪音問題；(丁)改善噪音必須交給環保局處理，一般人沒有責任參與。", "o": ["甲丙", "乙丁", "甲乙", "丙丁"], "a": 2, "e": "(甲) dB 是響度單位，正確。(乙) dB 愈大愈吵、愈不舒服，正確。\n(丙) 事先申請仍要顧及噪音，錯。(丁) 改善噪音人人有責，錯。→ 甲乙。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-126", "no": "126", "c": "k8", "src": "講義 p.104 基礎題 第 18 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "要隔絕噪音，下列哪一種方式無法達成？", "o": ["汽、機車裝防盜器", "高架橋的隔音牆裝吸音板", "窗戶採用真空密閉的處理", "錄音室的吸音牆"], "a": 0, "e": "防盜器是發出聲音的裝置，本身就可能製造噪音，不能隔絕噪音 → (A)。\n吸音板、真空窗、吸音牆都能減少噪音。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-127", "no": "127", "c": "k9", "src": "講義 p.104 素養題 第 1 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "科南為了要打開一個均位在同一八度音內的音調為 Fa (4)、Sol (5)、Si (7)、Re (2) 的音樂鎖，他選取四個相同酒杯，並倒入不同高度的酒配合音箱鎖，如右圖，再以嘴唇貼著杯口吹氣，以獲得四個音調來將鎖打開，請問他吹奏的順序應為何？", "o": ["abcd", "adcb", "bcda", "dcba"], "a": 2, "e": "用嘴「吹」酒杯，振動的是杯內空氣柱：酒愈多 → 空氣柱愈短 → 音調愈高。\n由圖：a 酒最少、d 酒最多 → 頻率 a＜b＜c＜d，依序對應 Re、Fa、Sol、Si。\n要吹 Fa、Sol、Si、Re → b、c、d、a。", "h": [], "rep": false, "img": "s3-q127", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-128", "no": "128", "c": "k9", "src": "講義 p.104 素養題 第 2 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下圖為妮妮向小櫻演示共振現象實驗的過程。面對小櫻的質疑，妮妮增加下列哪一個實驗來說服小櫻最合適？", "o": ["減輕敲擊音叉的力量，觀察敲擊後是否會共振", "將其中一支音叉更換成頻率為 500 Hz 的音叉，觀察敲擊後是否會共振", "將兩支音叉更換成頻率同為 500 Hz 的兩支音叉，觀察敲擊後是否會共振", "將其中一支音叉更換成頻率為 360 Hz 但大小不同的音叉，觀察敲擊後是否會共振"], "a": 1, "e": "小櫻懷疑「頻率不同的音叉也會共振」。\n要說服她，就把其中一支換成不同頻率（500 Hz），敲擊後如果另一支不會振動，就證明只有頻率相同才會共振 → (B)。", "h": [], "rep": false, "img": "s3-q128", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-129", "no": "129", "c": "k9", "src": "講義 p.104 素養題 第 3 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "大雄和靜宜一起到國家音樂廳去聽交響樂演奏會，在交響樂演奏會中，有許多種樂器，而藉由這些樂器可演奏出非常美妙的音樂。低音提琴是將弦線裝在有開口的木盒上，其主要目的為何？", "o": ["增加美觀", "增加音色", "使聲音加大", "演奏的時候，琴身會比較穩"], "a": 2, "e": "弦線裝在有開口的木盒（共鳴箱）上，利用盒內空氣共振，使聲音變大。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-130", "no": "130", "c": "k8", "src": "講義 p.104 素養題 第 4 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "承上題，擊鼓的人若改變敲擊鼓的力氣，可以改變聲音的哪個因素？", "o": ["音調", "音色", "速率", "響度"], "a": 3, "e": "敲鼓的力氣大小改變的是振幅 → 響度。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-131", "no": "131", "c": "k9", "src": "講義 p.104 素養題 第 5 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "承上題，小提琴手以右手拉弓，而左手手指不停地移動按弦的位置，其左手的作用是用為了調整下列何者？", "o": ["聲音的響度", "聲音的音調", "聲音的音色", "聲音的速率"], "a": 1, "e": "左手移動按弦位置，改變振動弦的長度 → 改變頻率 → 調整音調。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-132", "no": "132", "c": "k8", "src": "講義 p.104 素養題 第 6 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "承上題，在演奏會中，大雄和靜宜可以分辨出小喇叭與法國號的聲音，這是因為兩者所發出的聲音有何不同？", "o": ["音色不一樣", "響度不一樣", "音調不一樣", "音速不一樣"], "a": 0, "e": "不同樂器的波形不同 → 音色不同，所以能分辨小喇叭與法國號。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-133", "no": "133", "c": "k8", "src": "講義 p.105 優良經典題 第 1 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "曉娟分別敲擊數支音叉，其聲音在儀器上顯示之波形分別如下圖所示，橫軸（t）表示時間，縱軸（y）表示聲波振動的位移。若每一支音叉發出的聲音都是單一頻率，則哪些圖形可能來自同一音叉？", "o": ["甲、乙", "甲、丙", "乙、丁", "丙、丁"], "a": 1, "e": "同一支音叉不管振幅大小，頻率都一樣。逐一算頻率（每秒幾個波）：\n甲：0.04 秒 4 個波 → 100 Hz；乙：0.04 秒 1.25 個波 → 31.25 Hz；\n丙：0.02 秒 2 個波 → 100 Hz；丁：0.02 秒 1.5 個波 → 75 Hz。\n甲、丙頻率相同 → 可能是同一支音叉。", "h": ["同一支音叉，哪一個量一定相同？", "頻率＝波數÷時間，注意每張圖的時間刻度不同。"], "rep": false, "img": "s3-q133", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-134", "no": "134", "c": "k8", "src": "講義 p.105 優良經典題 第 2 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "右圖是童謠「小蜜蜂」的歌詞與樂譜，在小萍唱到「大家一齊」這四個字的期間，聲波的音調逐漸升高。此期間聲波音調逐漸升高，主要是因為下列何種變化？", "o": ["聲波的振幅逐漸增加", "聲波的頻率逐漸變低", "小萍聲帶每回振動一次的時間逐漸增加", "小萍聲帶每秒來回振動的次數逐漸增加"], "a": 3, "e": "音調升高 → 頻率變高 → 聲帶每秒振動的次數增加。\n(C) 每振動一次的時間（週期）應該是變短。振幅影響響度。", "h": [], "rep": false, "img": "s3-q134", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-135", "no": "135", "c": "k8", "src": "講義 p.105 優良經典題 第 3 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "現今智慧型手機可下載許多不同的 App（應用程式），其中一些可用來測量週遭聲波的音量，當音量愈大時，App 顯示的數值也愈大，則此數值的大小主要與聲波的何種性質有關？", "o": ["波長", "波速", "振幅", "頻率"], "a": 2, "e": "音量（響度）由振幅決定，振幅愈大，App 的分貝數愈大。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-136", "no": "136", "c": "k8", "src": "講義 p.105 優良經典題 第 4 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "樂譜上常用 f、p 等力度記號來表示樂曲在此處的音量（響度）大小應該如何變化，此類力度記號與聲波的下列何種特性最相關？", "o": ["波長", "波速", "頻率", "振幅"], "a": 3, "e": "力度記號 f（強）、p（弱）表示響度大小，和振幅最相關。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-137", "no": "137", "c": "k8", "src": "講義 p.105 優良經典題 第 5 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "聽力檢查會分別對左右耳做檢測，每次播放單一頻率、單一音量的聲音，在相同頻率中找出單耳能夠聽見最低音量的聲音，並做成紀錄。右圖為美怡所做的聽力檢查紀錄，依據此紀錄，下列敘述何者正確？", "o": ["她的左耳可聽見頻率 125 Hz、音量 10 dB 的聲音", "她的左耳聽不見頻率 8,000 Hz、音量 100 dB 的聲音", "她的右耳可聽見頻率 250 Hz、音量 40 dB 的聲音", "她的右耳聽不見頻率 4,000 Hz、音量 70 dB 的聲音"], "a": 3, "e": "圖上每個點是「剛好聽得到」的最小音量，音量要大於等於這個值才聽得到。\n左耳（●）125 Hz 要 20 dB，10 dB 聽不到，(A) 錯；左耳 8000 Hz 只要 50 dB，100 dB 聽得到，(B) 錯。\n右耳（▲）250 Hz 要 60 dB，40 dB 聽不到，(C) 錯；右耳 4000 Hz 要 80 dB，70 dB 聽不到，(D) 正確。", "h": ["圖上的點代表「最低能聽見的音量」。", "比較選項音量和圖上的值，比較大才聽得到。"], "rep": false, "img": "s3-q137", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-138", "no": "138", "c": "k10", "src": "講義 p.107 類題 1 第 (1) 小題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "大雄準備兩支空心水管及一塊鐵板，將鐵板直立在桌上，一支水管內放一個時鐘，如右圖所示。大雄將耳朵附於另一支水管，傾聽時鐘滴答聲。另一支水管要放在甲、乙、丙哪個位置，聽到的時鐘滴答聲最響亮？", "o": ["甲", "乙", "丙", "都一樣"], "a": 1, "e": "聲音反射遵守反射定律：入射角＝反射角。\n乙的位置和時鐘那支水管對稱（夾角相同），反射的聲音正好進入耳朵 → 最響亮。", "h": [], "rep": false, "img": "s3-q138", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-139", "no": "139", "c": "k10", "src": "講義 p.107 類題 1 第 (2) 小題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "承上題，若把鐵板改成棉布，其餘條件不變，則聽到的響度有何變化？", "o": ["變大", "變小", "不變", "變零"], "a": 1, "e": "棉布柔軟、表面不規則，會吸收聲波，反射的聲音變少 → 響度變小（但不會完全為零）。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-140", "no": "140", "c": "k10", "src": "講義 p.107 隨堂練習 1 第 1 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列何者不是回聲？", "o": ["耳朵聽到耳機放出的聲音", "在山谷間高喊後，傳過來的聲音", "汽車利用倒車雷達，所收到的聲波", "打雷後的隆隆聲"], "a": 0, "e": "回聲是聲音遇到障礙物反射回來的聲音。\n耳機的聲音直接傳到耳朵，沒有反射 → 不是回聲。倒車雷達、山谷回音、雷聲隆隆都有反射。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-141", "no": "141", "c": "k10", "src": "講義 p.107 隨堂練習 1 第 2 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "學校的大禮堂若要減少回音的干擾，下列何種設計是沒有效果的？", "o": ["加大大禮堂的空間", "裝設吸音板", "四周加掛布幔", "禮堂在設計上，採用不對稱的牆"], "a": 0, "e": "空間加大，聲音還是會遇到牆壁反射，而且回聲時間差變大更容易聽到 → 沒有效果。\n吸音板、布幔會吸收聲波；不對稱的牆會讓聲音分散反射，都能減少回音干擾。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-142", "no": "142", "c": "k11", "src": "講義 p.109 隨堂練習 2 第 1 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "某振動體每分鐘振動 600 次，則一般人可因此而聽到何種頻率的聲音？", "o": ["600 赫", "10 赫", "300 赫", "根本聽不到聲音"], "a": 3, "e": "每分鐘 600 次 → 頻率＝600÷60＝10 Hz。\n低於 20 Hz 是次聲波，人耳聽不到。", "h": ["先換算成每秒振動幾次。", "人耳能聽的範圍是多少？"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-143", "no": "143", "c": "k11", "src": "講義 p.109 隨堂練習 2 第 2 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "蝙蝠飛行時是利用回聲探測牆壁等障礙物，但其所發出的聲音，人耳卻聽不到，是因為下列哪一項原因？", "o": ["響度太小", "頻率太高", "波形太亂", "音速太快"], "a": 1, "e": "蝙蝠發出的是超聲波（頻率高於 20000 Hz），超過人耳範圍，所以聽不到。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-144", "no": "144", "c": "k11", "src": "講義 p.112 基礎題 第 12 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "漁夫在海上捕魚時，常使用可接收及發射超聲波的儀器，從海面向著正下方的海底探測魚群的狀況。假設在海水中超聲波的傳播速率為 1500 m / s，則下列敘述何者正確？", "o": ["發射超聲波 0.04 秒後傳回某魚群的訊息，該魚群在海面下 30 m 處", "使用超聲波探測海中的魚群時，是運用聲音折射原理得知魚群的位置", "使用超聲波探測魚群的位置，原因是有超聲波能在海水中傳播", "若超聲波從海水中傳入空氣中，其傳播速率不會改變"], "a": 0, "e": "聲納測距：距離＝v×t÷2＝1500×0.04÷2＝30 m → (A) 正確。\n探測魚群利用聲波「反射」，不是折射，(B) 錯；一般聲波也能在海水中傳播，(C) 錯。\n從海水進入空氣，速率會變慢，(D) 錯。", "h": ["0.04 秒是去程加回程的時間。", "距離＝聲速×時間÷2。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-145", "no": "145", "c": "k11", "src": "講義 p.112 基礎題 第 13 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列何者不是超聲波的應用？", "o": ["觀察母體內胎兒的儀器", "醫院使用儀器來粉碎腎結石病人的結石", "耳溫槍測量溫度", "清洗浸在溶劑中的精密機械或工具"], "a": 2, "e": "耳溫槍是偵測人體發出的紅外線，紅外線是電磁波，不是超聲波 → (C)。\n產檢、震碎結石、超音波清洗都是超聲波的應用。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-146", "no": "146", "c": "k11", "src": "講義 p.112 基礎題 第 14 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "有一艘海底探測船，以時速 20 公里向東行駛，並每隔 10 分鐘，利用聲納探測海底的深度並記錄之，若其回聲接收時間為 30 秒、15 秒、28 秒、5 秒、5 秒，則海底的地形可能為下列何者？", "o": ["圖A剖面", "圖B剖面", "圖C剖面", "圖D剖面"], "a": 1, "e": "回聲時間愈長，海底愈深。依序 30、15、28、5、5 秒 → 深、淺、深、很淺、很淺。\n船向東走，海底由西到東應該是：深 → 變淺 → 又變深 → 很淺並維持 → 對照圖選 (B)。", "h": [], "rep": false, "img": "s3-q146", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-147", "no": "147", "c": "k11", "src": "講義 p.112 素養題 第 1 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "潛艇在水面下方 300 公尺深的地方發出超聲波，藉以探測空中敵方直升機的位置。如右圖所示，經 1.2 秒後，收到由直升機反射回來的聲波。請問直升機的位置在水面上方多少公尺？（空氣中聲速每秒 300 公尺，水中聲速每秒 1500 公尺）", "o": ["120", "150", "240", "300"], "a": 0, "e": "超聲波先在水中走 300 m，再在空氣中走 x m 到直升機，來回共 1.2 秒，單程 0.6 秒。\n300÷1500＋x÷300＝0.6 → 0.2＋x÷300＝0.6 → x＝120 公尺。", "h": ["1.2 秒是來回，單程是幾秒？", "單程時間＝水中時間＋空氣中時間。"], "rep": false, "img": "s3-q147", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-148", "no": "148", "c": "k10", "src": "講義 p.112 素養題 第 2 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "有一班北上自強號列車，以 8 公尺／秒的車速等速接近隧道（隧道上方有山壁），司機按鳴喇叭，10 秒後司機聽到由山壁傳來的回聲，則當司機按喇叭時，火車與隧道的距離為多少公尺？（當時氣溫為 15 °C）", "o": ["3400", "1660", "1740", "1320"], "a": 2, "e": "15 °C 聲速 340 m/s。火車靠近山壁：聲音走的路＋火車走的路＝2 倍距離。\n距離＝(340×10＋8×10)÷2＝(3400＋80)÷2＝1740 公尺。", "h": ["畫圖：聲音去再回來，火車同時也往前開。", "聲音路程＋火車路程＝2×鳴笛時的距離。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-149", "no": "149", "c": "k10", "src": "講義 p.112 素養題 第 3 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "承上題，當火車遠離隧道後，司機於距離隧道 830 公尺處，再次按鳴喇叭，若火車車速不變，則要經歷幾秒，才能聽見由火車後方傳來的回聲？", "o": ["5", "4", "8", "3"], "a": 0, "e": "火車遠離山壁：聲音路程－火車路程＝2×830。\n340t－8t＝1660 → 332t＝1660 → t＝5 秒。", "h": ["火車遠離時，聲音回來要追上已經開走的火車。", "列式：340t－8t＝2×830。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-150", "no": "150", "c": "k4", "src": "講義 p.114 自我評量 第 1 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "如右圖，一繩波依箭頭方向傳遞，最初波形如甲圖所示；2 秒後，波形如乙圖所示。請問下列敘述何者正確？", "o": ["波長為 20 cm", "週期為 2 秒", "振幅為 6 cm", "波速為 10 cm / s"], "a": 3, "e": "甲圖中 20 cm 是半個波 → 波長 40 cm，(A) 錯。\n6 cm 是波峰到波谷 → 振幅 3 cm，(C) 錯。\n2 秒內波形前進半個波 → 週期 4 秒，(B) 錯；波速＝40÷4＝10 cm/s，(D) 正確。", "h": ["先讀出波長和振幅（注意標示的是哪兩點）。", "比較甲、乙兩圖，2 秒內波前進了幾個波？"], "rep": false, "img": "s3-q150", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-151", "no": "151", "c": "k4", "src": "講義 p.114 自我評量 第 2 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "某繩波在時刻 t=0 時的波形如右圖，假設波的週期為 0.4 秒，則經 0.1 秒後，繩波的波形為下列何者？", "o": ["圖A波形", "圖B波形", "圖C波形", "圖D波形"], "a": 1, "e": "週期 0.4 秒，經過 0.1 秒＝1/4 個週期 → 整個波形沿前進方向（向右）移動 1/4 個波長，形狀不變。\n把原圖往右平移 1/4 個波長，再看 P 點的位置 → 對照選項是 (B)。\n★ 經過 1/4 週期，每個點都由平衡位置移到波峰（或波谷），或由波峰（波谷）回到平衡位置。", "h": ["0.1 秒是幾分之幾個週期？", "波形向前移動的距離＝（經過時間÷週期）×波長。"], "rep": false, "img": "s3-q151", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-152", "no": "152", "c": "k8", "src": "講義 p.114 自我評量 第 3 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "在教室內同時振動的甲、乙兩音叉，其產生的波形如右圖，則兩波的何種性質是甲>乙？", "o": ["波長", "頻率", "週期", "波速"], "a": 1, "e": "在相同時間、相同空氣中，甲的疏密波排得較密 → 波長較短 → 頻率較高。\n所以甲＞乙的是頻率；甲的波長、週期都比乙小，波速相同。", "h": [], "rep": false, "img": "s3-q152", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-153", "no": "153", "c": "k6", "src": "講義 p.114 自我評量 第 4 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列各種方法，哪些無法證明物體因振動發出聲音？", "o": ["在發聲的鼓面上灑上米粒", "將通電的電鈴放入玻璃罩中抽氣成真空", "以振動的音叉接觸水面", "將音叉微微接觸空玻璃杯邊緣"], "a": 1, "e": "把電鈴放進玻璃罩抽成真空，證明的是「聲音傳播需要介質」，不是「物體振動發聲」→ (B)。\n米粒跳動、音叉濺水花、音叉碰杯子都能看出發聲體在振動。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-154", "no": "154", "c": "k1", "src": "講義 p.114 自我評量 第 5 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "在無風的狀況下，有關聲音在空氣中傳播時的特性，下列敘述何者正確？", "o": ["聲音在空氣中傳播時，是一種能量的傳遞", "聲波的傳播方向與空氣分子的運動方向相互垂直", "聲音在密度均勻的空氣中傳播時，任意位置都會發生反射", "空氣對聲音的傳播會形成阻礙，若沒有空氣，則聲音的傳播速率會更快"], "a": 0, "e": "聲波傳播的是能量，(A) 正確。\n空氣中的聲波是縱波，傳播方向和空氣分子振動方向平行，(B) 錯。\n聲音要遇到障礙物才反射，(C) 錯；沒有空氣根本無法傳聲，(D) 錯。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-155", "no": "155", "c": "k7", "src": "講義 p.114 自我評量 第 6 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "已知空氣和海水傳聲的速率各為每秒 340 公尺及每秒 1360 公尺，我方軍艦發射炮彈擊中敵艦，經由海水及空氣傳來的兩次爆炸聲相隔 12 秒，則敵艦和我方軍艦相距多少公尺？", "o": ["1224", "1360", "2720", "5440"], "a": 3, "e": "設距離 x 公尺：空氣傳來的時間－海水傳來的時間＝12 秒。\nx÷340－x÷1360＝12 → 4x÷1360－x÷1360＝12 → 3x＝16320 → x＝5440 公尺。", "h": ["哪一個先到？兩條路徑的時間差是 12 秒。", "列式 x÷340－x÷1360＝12，通分後計算。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-156", "no": "156", "c": "k7", "src": "講義 p.115 自我評量 第 7 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "某日室內溫度 20 °C，當頻率 200 次／秒的小提琴聲傳至室外時，測量到室外聲音的波長較室內聲音多出 1.5 公分，求當日室外的氣溫為多少 °C？", "o": ["22", "25", "30", "32"], "a": 1, "e": "頻率不變（200 Hz），波長和聲速成正比。\n室內 20 °C：v＝331＋0.6×20＝343 m/s，λ＝343÷200＝1.715 m。\n室外 λ＝1.715＋0.015＝1.73 m → v＝200×1.73＝346 m/s → 331＋0.6T＝346 → T＝25 °C。", "h": ["頻率不變，波長變長代表聲速變快。", "先算室內聲速和波長，再算室外聲速，最後代回 v＝331＋0.6T。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-157", "no": "157", "c": "k8", "src": "講義 p.115 自我評量 第 8 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "有關樂器演奏時，我們所聽到的聲音，下列哪一項敘述錯誤？", "o": ["發出的聲音愈大，傳播的速率愈快", "頻率愈大的，聽起來聲音較高", "能區分各種樂器的聲音，是因為它們的音色不同", "樂器引起空氣的振動愈大者，聲音愈強"], "a": 0, "e": "聲音大小（響度）和傳播速率無關，速率只由介質決定 → (A) 錯誤，選它。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-158", "no": "158", "c": "k5", "src": "講義 p.115 自我評量 第 9 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "一鼓手以每秒 2 次的頻率敲打每秒鐘振動 3400 次的鼓面，已知空氣傳聲速率為 340 m / s，則鼓聲的波長為多少 m？", "o": ["0.1", "10", "170", "1700"], "a": 0, "e": "聲音的頻率是鼓面振動的頻率 3400 Hz，不是敲打的次數。\nλ＝v÷f＝340÷3400＝0.1 m。", "h": ["發出聲音的頻率是「敲的次數」還是「鼓面振動的次數」？", "λ＝v÷f。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-159", "no": "159", "c": "k9", "src": "講義 p.115 自我評量 第 10 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "有關聲音的敘述，下列何者正確？", "o": ["聲音唯有在空氣中才能傳播", "聲音的高低稱為響度，通常以分貝為單位", "將吉他弦線拉緊，撥弦時弦線每秒振動的次數會增加", "聲速超過 340 m / s 的聲音，稱為超聲波"], "a": 2, "e": "聲音在固體、液體、氣體都能傳播，(A) 錯。\n聲音高低是音調，單位赫茲；分貝是響度單位，(B) 錯。\n弦拉緊 → 振動變快，(C) 正確。\n超聲波是「頻率」高於 20000 Hz，和聲速無關，(D) 錯。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-160", "no": "160", "c": "k10", "src": "講義 p.115 自我評量 第 11 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列有關「回聲」與「聲音反射」的敘述，何者錯誤？", "o": ["在空曠的山谷中大聲說話，會有回聲，可說明聲音的反射現象", "利用傳聲筒，可將聲音傳得更遠，這是利用聲音反射的原理", "在小房間內說話無法聽見回聲，這是因為空間太小，聲音沒有產生反射的緣故", "聲音反射之後，頻率不變，但是響度將變小"], "a": 2, "e": "小房間內聲音照樣會反射，只是牆壁太近，回聲和原聲相差不到 0.1 秒、重疊在一起，聽起來反而更響亮 → (C) 錯誤，選它。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-161", "no": "161", "c": "k11", "src": "講義 p.115 自我評量 第 12 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "敲擊一支頻率為 400 Hz 的音叉，測得其發出的聲音在空氣中每秒傳播 350 m，若同時用聲納發出 40000 Hz 的超聲波，則下列有關兩種聲波的敘述何者正確？", "o": ["超聲波的波速為 35000 m / s", "超聲波的振幅是音叉振幅的 100 倍", "超聲波是種令人不舒服的噪音", "超聲波的波長較音叉所發出的聲波短"], "a": 3, "e": "同在空氣中，兩種聲波速率相同（350 m/s），(A) 錯。\n題目沒有給振幅資訊，(B) 錯；人聽不到超聲波，不是噪音，(C) 錯。\n速率相同，頻率愈高波長愈短 → 超聲波波長較短，(D) 正確。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-162", "no": "162", "c": "k11", "src": "講義 p.115 自我評量 第 13 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "阿三博士用超聲波儀檢測飛機機翼內部裂縫，從發出至回傳只有 10⁻⁴ 秒，試問機翼裂縫距表面多少公尺？（機翼金屬聲速為 6000 公尺／秒）", "o": ["0.03", "0.06", "0.3", "0.6"], "a": 2, "e": "從發出到回傳是來回：距離＝v×t÷2＝6000×10⁻⁴÷2＝0.6÷2＝0.3 公尺。", "h": ["10⁻⁴ 秒是去程還是來回？", "距離＝聲速×時間÷2。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-163", "no": "163", "c": "k9", "src": "講義 p.117 科學素養篇 第 1 題", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "次聲波是指頻率低於 20 Hz 的聲波，人類聽不到，但大象、長頸鹿和藍鯨等動物可用次聲波互通訊息。次聲波的頻率極低，不易被水和空氣吸收，可穿透大氣、海水及鋼筋水泥建築物。次聲波穿透人體時，會造成頭暈、煩躁、耳鳴、噁心、心悸等症狀。人體內臟的振動頻率和次聲波頻率相近（0.01～20 Hz），尤其是腹腔、胸腔，如果外來的次聲波頻率與內臟的振動頻率相似或相同，就會引起內臟的共振，使人產生上述症狀，甚至受損而喪命。", "fig": "", "q": "次聲波對人體有潛在的危險性，其主要原因為何？", "o": ["容易穿透人體，損害內臟", "波長短，在人體中容易危害細胞", "人體內臟容易受次聲波的影響而共振", "傳播速度快，人體器官容易受到破壞"], "a": 2, "e": "依文章：次聲波頻率和人體內臟振動頻率相近，會引起內臟共振，造成傷害 → (C)。\n次聲波的波長很長、速率和一般聲波相同。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-164", "no": "164", "c": "k1", "src": "自修 p.109 觀摩經典題 第 2 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "平靜無風的下午，在許願池上 O 點丟入一枚硬幣，使水面上產生一個圓形水波，已知圓形水波的半徑每秒增加 1 m。若丟入硬幣前，在水面上距離 O 點 1 m 及 2 m 的 P、Q 兩點，分別有一片落葉，且 O、P、Q 在同一直線上，如右圖所示，則硬幣丟入水中 3 秒後，兩片落葉的距離約為多少？", "o": ["3 m", "5 m", "6 m", "9 m"], "a": 0, "e": "水波只傳遞能量，落葉只在原地上下振動，不會被推開。\nP 在 O 左邊 1 m、Q 在 O 右邊 2 m → 兩片落葉相距一直是 3 m。", "h": [], "rep": false, "img": "s3-q164", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-165", "no": "165", "c": "k4", "src": "自修 p.109 觀摩經典題 第 3 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "一條輕繩的一端固定於水平桌面的桌緣上，拉直此繩使其呈水平後，再以固定頻率鉛直上下振動，產生相同頻率的繩波，其示意圖如右上圖所示。繩波上一點 P 與桌面水平線的鉛直高度與時間的關係如下表所示，依據此表推論下列何者最可能是此繩波的週期？", "o": ["1.0 × 10⁻² s", "1.5 × 10⁻² s", "2.0 × 10⁻² s", "3.0 × 10⁻² s"], "a": 3, "e": "看 P 點高度：t＝0 時 5.0，到 t＝3.0（×10⁻² s）時又回到 5.0 → 完成一次振動。\n週期＝3.0×10⁻² s。", "h": ["找出 P 點第一次「回到原來位置」的時間。"], "rep": false, "img": "s3-q165", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-166", "no": "166", "c": "k4", "src": "自修 p.109 觀摩經典題 第 4 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "某音叉發出一單一頻率的聲音，它的特性顯示在儀器上，如右圖所示，y 為其振動的位移。此音叉發出聲音的頻率為下列何者？", "o": ["1000 Hz", "800 Hz", "400 Hz", "100 Hz"], "a": 2, "e": "1/100 秒內有 4 個完整的波 → 頻率＝4÷0.01＝400 Hz。", "h": ["數一數 1/100 秒內有幾個完整的波。", "頻率＝波數÷時間。"], "rep": false, "img": "s3-q166", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-167", "no": "167", "c": "k5", "src": "自修 p.109 觀摩經典題 第 5 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "以繩波產生器製造數個連續且完全相同的繩波，繩波上某一點的振動位移與時間關係如右圖所示。若當時繩波傳播速率為 2 m / s，則此繩波的波長為下列何者？", "o": ["4 cm", "10 cm", "0.8 m", "5 m"], "a": 2, "e": "由圖：兩波峰相隔 0.4 秒 → 週期 T＝0.4 s。\nλ＝v×T＝2×0.4＝0.8 m。", "h": ["從位移－時間圖讀出週期。", "λ＝v×T。"], "rep": false, "img": "s3-q167", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-168", "no": "168", "c": "k4", "src": "自修 p.109 類題演練 第 1 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "吉他上的弦線，調整其緊度到適當程度後，撥動使其在 5 秒內振動了 1250 次，則此弦振動的週期為多少秒？", "o": ["0.04", "0.004", "25", "250"], "a": 1, "e": "週期＝時間÷次數＝5÷1250＝0.004 秒。", "h": ["週期是振動一次所需的時間。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-169", "no": "169", "c": "k5", "src": "自修 p.109 類題演練 第 2 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "波速為 40 cm / s 的連續週期波，波形如右圖所示，則此波的頻率為多少 Hz？", "o": ["4", "5", "6", "8"], "a": 1, "e": "由圖：12 cm 內有 1.5 個波 → 波長＝12÷1.5＝8 cm。\nf＝v÷λ＝40÷8＝5 Hz。", "h": ["12 cm 裡有幾個波？", "f＝v÷λ。"], "rep": false, "img": "s3-q169", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-170", "no": "170", "c": "k6", "src": "自修 p.116 基本學力篇 第 1 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "高品質氣密式隔音窗戶，除了窗框間有軟橡膠條隔音，玻璃片使用雙層玻璃設計，兩玻璃片之間以下列何種方式處理，隔音效果最好？", "o": ["填充氮氣", "抽成真空", "填充保麗龍", "貼反光紙"], "a": 1, "e": "真空不能傳聲，兩層玻璃之間抽成真空，隔音效果最好。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-171", "no": "171", "c": "k7", "src": "自修 p.116 基本學力篇 第 2 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "乾燥無風之天氣，中午溫度較早晨溫度高 5 °C，則中午比早晨之聲音速率為下列何者？", "o": ["快 5 m / s", "快 3 m / s", "慢 5 m / s", "慢 3 m / s"], "a": 1, "e": "溫度每升高 1 °C，聲速快 0.6 m/s。高 5 °C → 快 0.6×5＝3 m/s。", "h": ["每升高 1 °C 聲速增加多少？"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-172", "no": "172", "c": "k7", "src": "自修 p.116 基本學力篇 第 3 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "聲音在空氣、水及玻璃三種介質中傳播速率大小順序，下列何者正確？", "o": ["空氣>水>玻璃", "水>玻璃>空氣", "玻璃>空氣>水", "玻璃>水>空氣"], "a": 3, "e": "聲速：固體＞液體＞氣體 → 玻璃＞水＞空氣。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-173", "no": "173", "c": "k5", "src": "自修 p.116 基本學力篇 第 4 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "在空氣中分別敲擊兩音叉，產生波長分別為 1 m、0.5 m 的兩聲波，則兩聲波在空氣中聲速比為下列何者？", "o": ["1：1", "1：2", "2：1", "4：1"], "a": 0, "e": "同在空氣中，聲速由介質決定，與波長無關 → 1：1。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-174", "no": "174", "c": "k3", "src": "自修 p.116 基本學力篇 第 5 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "空氣中的聲波在傳播時，空氣分子振動方向和波傳播方向平行，有關此聲波之敘述，下列何者正確？", "o": ["屬於橫波", "屬於高低波", "屬於疏密波", "屬於電磁波"], "a": 2, "e": "空氣分子振動方向和波傳播方向平行 → 縱波，又叫疏密波。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-175", "no": "175", "c": "k7", "src": "自修 p.116 基本學力篇 第 6 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "已知在乾燥無風之空氣中，溫度 0 °C 時，聲速為 331 m / s，每上升 1 °C，速率增加 0.6 m / s，某天中午空氣乾燥無風，氣溫為 18 °C，則此時聲速為何？", "o": ["341.8 m / s", "340.0 m / s", "338 m / s", "336 m / s"], "a": 0, "e": "v＝331＋0.6×18＝331＋10.8＝341.8 m/s。", "h": ["代入 v＝331＋0.6T。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-176", "no": "176", "c": "k6", "src": "自修 p.116 基本學力篇 第 7 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列何者無法說明聲音的產生，物體需有振動？", "o": ["手放喉嚨處說話，可感覺聲帶的振動", "手按住振動中的音叉，聲音立即停止", "發出聲響之音叉，接觸水面會濺起水花", "密閉玻璃罩中空氣抽出，將聽不到玻璃罩內的鈴聲"], "a": 3, "e": "抽氣後聽不到鈴聲，說明的是「聲音傳播需要介質」，不能說明「發聲需要振動」→ (D)。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-177", "no": "177", "c": "k7", "src": "自修 p.116 基本學力篇 第 8 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "空氣乾燥無風，由甲處鳴笛傳到乙地，早晨聲速為 340 m / s，中午聲速為 360 m / s，兩時段笛聲傳到乙地相差 0.2 秒，則甲、乙兩地相距多少公尺？", "o": ["1024", "1224", "1424", "1624"], "a": 1, "e": "設距離 S：早晨時間－中午時間＝0.2 秒。\nS÷340－S÷360＝0.2 → S×(360－340)÷(340×360)＝0.2 → S＝0.2×122400÷20＝1224 公尺。", "h": ["早晨聲速慢，花的時間比較長。", "列式 S÷340－S÷360＝0.2。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-178", "no": "178", "c": "k7", "src": "自修 p.119 觀摩經典題 第 1 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "村中的喇叭同時向左右廣播著重要事項，位於喇叭左右兩端的阿鳳與千千聽到廣播的時間差為 0.5 s，其示意圖如下圖所示。若圖中三者在同一直線上，且忽略風及溫度對聲速的影響，已知下列選項中有一項是阿鳳與千千的距離，依上述條件推論，何者為兩人之間的距離？（當時聲速為 340 m / s）", "o": ["17 m", "34 m", "150 m", "300 m"], "a": 3, "e": "兩人聽到廣播相差 0.5 秒 → 兩人到喇叭的距離相差 340×0.5＝170 m。\n喇叭在兩人中間，兩人的距離＝遠的距離＋近的距離，一定大於 170 m → 只有 300 m 合理。", "h": ["時間差 0.5 秒代表兩人到喇叭的距離差多少？", "兩人分在喇叭兩側，總距離和距離差的大小關係是什麼？"], "rep": false, "img": "s3-q178", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-179", "no": "179", "c": "k7", "src": "自修 p.120 觀摩經典題 第 2 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "垃圾車收垃圾地點的順序及各站間距離如右圖所示。垃圾車每停一站便會開始播放音樂提醒附近的居民來倒垃圾，垃圾車在第 1 站停下來播放音樂並收垃圾，若忽略風及溫度對聲速的影響，則此時在第 2 站的小強與第 3 站的小樂聽到音樂傳來的時間差為下列何者？（當時聲速為 340 m / s）", "o": ["0", "1.0 s", "1.5 s", "2.0 s"], "a": 1, "e": "第 2 站離第 1 站 170 m；第 3 站離第 1 站 170＋340＝510 m。\n距離差 340 m → 時間差＝340÷340＝1.0 秒。", "h": ["分別算出第 2、3 站到第 1 站的距離。", "時間差＝距離差÷聲速。"], "rep": false, "img": "s3-q179", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-180", "no": "180", "c": "k7", "src": "自修 p.120 觀摩經典題 第 3 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "靜止在海面上的甲船發出聲波訊號，訊號同時由空氣及海水以直線傳至同樣靜止在海面上的乙船，如右圖所示。假設當時無風，且海面平靜，在空氣中的聲速為 340 m / s，在海水中的聲速為 1700 m / s，則乙船先後接收到上述兩個聲波訊號的時間差最接近下列何者？", "o": ["0.3 秒", "0.5 秒", "1.6 秒", "2 秒"], "a": 2, "e": "空氣：680÷340＝2 秒；海水：680÷1700＝0.4 秒。時間差＝2－0.4＝1.6 秒。", "h": ["分別算兩條路徑的時間。"], "rep": false, "img": "s3-q180", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-181", "no": "181", "c": "k8", "src": "自修 p.120 觀摩經典題 第 4 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "「白噪音」為一種人類可聽見的聲波，此聲波在各頻率的響度大致相同。在自然界中，類似的聲音包括雨聲、海浪聲等，而家中電風扇所製造出的聲音也與白噪音相似。科學家研究發現，嬰兒處在此種白噪音的環境下，會比較容易入睡。根據上述，下列響度與頻率的關係圖，何者最適合用來表示此種幫助入睡的白噪音？", "o": ["響度 10 dB，頻率範圍 100～10000 Hz 曲線圖", "響度 100 dB，頻率範圍 100～10000 Hz 曲線圖", "響度 10 dB，頻率範圍 20000～2000000 Hz 曲線圖", "響度 100 dB，頻率範圍 20000～2000000 Hz 曲線圖"], "a": 0, "e": "白噪音是人聽得到的聲音（20～20000 Hz 之間），而且要幫助入睡，響度要小。\n→ 10 dB、頻率 100～10000 Hz 的 (A)。\n20000 Hz 以上人聽不到；100 dB 太吵。", "h": [], "rep": false, "img": "s3-q181", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-182", "no": "182", "c": "k7", "src": "自修 p.121 觀摩經典題 第 5 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "某處化學藥品倉庫發生爆炸，網路上出現很多目擊者拍攝的影片，其中一位目擊者當時拍攝的位置距離爆炸位置約 1.5 km，則有關此目擊者所拍攝的影片，下列描述何者最合理？", "o": ["影片中聽到爆炸聲後約經過 4～5 秒才看到此爆炸的爆炸火光", "影片中看到爆炸火光後約經過 4～5 秒才聽到此爆炸的爆炸聲", "影片中聽到爆炸聲後約經過 0.04～0.05 秒才看到此爆炸的爆炸火光", "影片中看到爆炸火光後約經過 0.04～0.05 秒才聽到此爆炸的爆炸聲"], "a": 1, "e": "光速極快，看到火光幾乎沒有延遲；聲音走 1.5 km 要 1500÷340≈4.4 秒。\n所以影片中先看到火光，約 4～5 秒後才聽到爆炸聲。", "h": ["光和聲音哪個先到？", "聲音走 1500 m 大約要幾秒？"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-183", "no": "183", "c": "k5", "src": "自修 p.121 類題演練 第 1 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "地震發生時，同時產生橫波和縱波，已知其波速分別為 4 公里／秒和 6 公里／秒，民國 88 年 9 月 21 日發生規模 7.3、震央在南投集集的地震，甲地接受到縱波和橫波時間差為 20 秒，則甲地與震源處距離為多少公里？", "o": ["240", "280", "320", "360"], "a": 0, "e": "縱波較快先到，橫波較慢後到。設距離 d：d÷4－d÷6＝20 → d÷12＝20 → d＝240 公里。", "h": ["哪一種波先到？", "列式：慢的時間－快的時間＝20 秒。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-184", "no": "184", "c": "k7", "src": "自修 p.121 類題演練 第 2 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "甲同學施放煙火時，煙火垂直等速上升到高空，經 6.8 秒甲同學看見煙火爆炸之亮光，再經 2 秒聽到爆炸聲，已知當時聲速為 340 公尺／秒，則煙火垂直上升速率為多少公尺／秒？", "o": ["90", "100", "120", "130"], "a": 1, "e": "光傳播時間可忽略：6.8 秒時煙火在高空爆炸。\n聲音傳下來花 2 秒 → 高度＝340×2＝680 m。\n上升速率＝680÷6.8＝100 m/s。", "h": ["先由聲音傳下來的時間算出爆炸高度。", "高度÷上升時間＝速率。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-185", "no": "185", "c": "k8", "src": "自修 p.121 類題演練 第 3 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "分別敲擊四支音叉產生聲音，經示波器顯示空氣中質點振動位移與時間關係如下，則哪一支音叉與其他三支頻率不同？", "o": ["圖A波形", "圖B波形", "圖C波形", "圖D波形"], "a": 3, "e": "比較相同時間內的波數：(A)(B)(C) 頻率相同，(D) 在相同時間內的波數較多 → 頻率不同。\n注意 (B) 只是振幅較大，頻率和 (A)(C) 一樣。", "h": [], "rep": false, "img": "s3-q185", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-186", "no": "186", "c": "k1", "src": "自修 p.121 類題演練 第 4 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "空氣中的聲音之敘述，下列何者正確？", "o": ["聲速只與空氣溫度有關", "空氣中聲波屬於高低波", "聲波傳播能量，不傳播物質", "聲波傳播方向與質點振動方向相同"], "a": 2, "e": "聲速和介質種類、溫度、溼度、風向都有關，(A) 錯。\n空氣中的聲波是縱波（疏密波），(B)(D) 錯。\n聲波傳播能量、不傳播物質，(C) 正確。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-187", "no": "187", "c": "k7", "src": "自修 p.121 類題演練 第 5 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "士兵與靶距離 1020 公尺，子彈飛行速率為 255 m / s，士兵擊發後經 7 秒聽到子彈中靶之聲響，若當時空氣乾燥無風，則氣溫為多少 °C？", "o": ["10", "15", "20", "25"], "a": 1, "e": "子彈飛到靶：1020÷255＝4 秒；剩下 7－4＝3 秒是聲音傳回來的時間。\n聲速＝1020÷3＝340 m/s → 331＋0.6T＝340 → T＝15 °C。", "h": ["7 秒包含子彈飛過去和聲音傳回來。", "求出聲速後代入 v＝331＋0.6T。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-188", "no": "188", "c": "k8", "src": "自修 p.130 基本學力篇 第 1 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "聲音傳到遠處響度會變小，是因為聲波的哪一項性質變小之故？", "o": ["頻率", "波形", "波長", "振幅"], "a": 3, "e": "聲音傳得愈遠，能量分散，振幅變小 → 響度變小。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-189", "no": "189", "c": "k8", "src": "自修 p.130 基本學力篇 第 2 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "以下五音同為 C 大調的音階，唱名依次為 Re、Mi、Fa、Sol、La，這五聲音是依據波的何種性質排列？", "o": ["波速由小而大排列", "頻率由小而大排列", "波長由小而大排列", "振幅由大而小排列"], "a": 1, "e": "Re、Mi、Fa、Sol、La 是音由低到高 → 頻率由小而大。\n（同在空氣中波速相同，波長是由大而小。）", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-190", "no": "190", "c": "k9", "src": "自修 p.130 基本學力篇 第 3 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "四支音叉資料如下：甲頻率 250 Hz、乙頻率 500 Hz、丙週期 2 × 10⁻³ 秒、丁週期 1 × 10⁻³ 秒，下列哪一組敲其一，可使另一支音叉產生共鳴？", "o": ["甲、乙", "乙、丙", "丙、丁", "丁、甲"], "a": 1, "e": "共鳴的條件：兩支音叉頻率相同。\n丙：f＝1÷(2×10⁻³)＝500 Hz；丁：f＝1÷(1×10⁻³)＝1000 Hz。\n乙 500 Hz 和丙 500 Hz 相同 → 乙、丙。", "h": ["共鳴需要什麼條件？", "把週期換成頻率：f＝1÷T。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-191", "no": "191", "c": "k9", "src": "自修 p.132 基本學力篇 第 18 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "有一樂器七條弦線由相同材質構成，緊度相同，但由下而上漸粗，如右圖所示，當左手分別按壓甲、乙、丙、丁處，撥動弦線時產生之聲音，何者音調最高？", "o": ["甲", "乙", "丙", "丁"], "a": 3, "e": "弦的材質、緊度相同時，弦愈細、振動部分愈短，音調愈高。\n丁按在下方較細的弦上，而且按壓點較靠右，能振動的弦最短 → 音調最高。", "h": [], "rep": false, "img": "s3-q191", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-192", "no": "192", "c": "k5", "src": "自修 p.132 基本學力篇 第 19 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "頻率同為 1000 Hz 的聲波，在 0 °C 空氣中、25 °C 空氣中、25 °C 水中及 25 °C 玻璃中傳播，何者波長最短？", "o": ["0 °C 空氣", "25 °C 空氣", "25 °C 水", "25 °C 玻璃"], "a": 0, "e": "頻率相同時，波長和聲速成正比，聲速最慢的波長最短。\n聲速：玻璃＞水＞25 °C 空氣＞0 °C 空氣 → 0 °C 空氣波長最短。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-193", "no": "193", "c": "k8", "src": "自修 p.132 基本學力篇 第 20 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "理化老師背對著同學整理黑板時，聽到座位上同學在聊天講話，立即能分辨出是小東和阿花在聊天，叫出姓名糾正，則老師是依據聲波的何種性質做出判斷？", "o": ["頻率", "波速", "振幅", "波形"], "a": 3, "e": "分辨出是誰在說話，靠的是音色 → 波形。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-194", "no": "194", "c": "k8", "src": "自修 p.133 進階學力篇 第 21 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "在相同空氣環境下所產生之四聲音如右表，有關空氣中傳播的敘述，下列何者正確？", "o": ["甲音調最低，但最大聲", "丁可傳得最遠，仍可聽見", "乙傳播速率最快", "丙相鄰兩密部距離最大"], "a": 0, "e": "甲頻率 262 Hz 最低 → 音調最低；95 dB 最大 → 最大聲，(A) 正確。\n響度最大的甲傳得最遠，丁 60 dB 最小，(B) 錯。\n同在空氣中速率相同，(C) 錯。\n甲頻率最低 → 波長（相鄰密部距離）最大，不是丙，(D) 錯。", "h": [], "rep": false, "img": "s3-q194", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-195", "no": "195", "c": "k8", "src": "自修 p.133 進階學力篇 第 22 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "吉他彈奏出優美的樂聲，演奏者演奏時，可以控制吉他樂聲的哪些性質？ (甲)音色；(乙)音調；(丙)聲速；(丁)響度。", "o": ["甲乙", "丙丁", "乙丁", "甲丙"], "a": 2, "e": "演奏者可以改變按弦位置（音調）和撥弦力道（響度）。\n音色由吉他本身決定，聲速由空氣決定 → 乙丁。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-196", "no": "196", "c": "k8", "src": "自修 p.133 進階學力篇 第 23 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "右表為 C 大調的四聲音，下列敘述何者正確？", "o": ["甲音調最高，但最小聲", "乙音調最低，且最小聲", "丙音調最高，且最大聲", "丁聲速最快"], "a": 1, "e": "音階由低到高 Do、Re、Mi、Fa、Sol、La、Si：乙 Re 最低，甲 Si 最高。\n響度：乙 50 dB 最小、丁 80 dB 最大。\n乙音調最低且最小聲 → (B)。同在空氣中聲速都相同。", "h": [], "rep": false, "img": "s3-q196", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-197", "no": "197", "c": "k8", "src": "自修 p.133 進階學力篇 第 24 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列聲音中，何者較易造成聽力的受損？", "o": ["65 dB、300 Hz", "110 dB、200 Hz", "90 dB、4000 Hz", "50 dB、5000 Hz"], "a": 1, "e": "響度太大（約 90 dB 以上，尤其 100 dB 以上）最容易傷害聽力 → 110 dB 的 (B)。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-198", "no": "198", "c": "k4", "src": "自修 p.133 進階學力篇 第 25 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "男生甲之聲音音調約在 85 Hz～155 Hz 之間，女生乙之聲音音調約在 165 Hz～256 Hz 之間，則下列敘述何者正確？", "o": ["甲聲速比乙快", "甲響度比乙大聲", "乙音色較單純", "乙聲波週期較甲小"], "a": 3, "e": "同在空氣中聲速相同，(A) 錯；題目沒說響度，(B) 錯；音色無法判斷，(C) 錯。\n乙頻率較高 → 週期較小，(D) 正確。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-199", "no": "199", "c": "k10", "src": "自修 p.142 基本學力篇 第 1 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列何者不屬於回聲？", "o": ["在山谷中大叫後的回音", "蝙蝠判斷障礙物位置的聲波", "先看到閃電再聽到的雷聲", "山谷間隆隆不絕的雷聲"], "a": 2, "e": "先看到閃電再聽到雷聲，是因為光速比聲速快，雷聲是直接傳來的，不是反射 → 不屬於回聲。\n山谷間隆隆不絕的雷聲則是多次反射的回聲。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-200", "no": "200", "c": "k11", "src": "自修 p.142 基本學力篇 第 2 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列哪一聲波，無法使人產生聽覺？", "o": ["20 dB、50 Hz", "50 dB、252 Hz", "80 dB、1200 Hz", "100 dB、10 Hz"], "a": 3, "e": "人耳聽 20～20000 Hz。10 Hz 是次聲波，再大聲也聽不到 → (D)。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-201", "no": "201", "c": "k11", "src": "自修 p.142 基本學力篇 第 3 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "超聲波具有下列何種特性？", "o": ["高頻率、波長極短", "高頻率、波長極長", "低頻率、極大振幅", "低頻率、極小振幅"], "a": 0, "e": "超聲波頻率很高（＞20000 Hz），同介質波速相同 → 波長很短。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-202", "no": "202", "c": "k10", "src": "自修 p.142 基本學力篇 第 4 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "在山谷間大力擊鼓一聲，經 4 秒後聽到由甲山壁反射回之回音，已知當時山谷間聲速為 348 公尺／秒，則甲山壁距擊鼓處距離為多少公尺？", "o": ["680", "696", "724", "742"], "a": 1, "e": "4 秒是來回時間：距離＝348×4÷2＝696 公尺。", "h": ["4 秒是單程還是來回？"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-203", "no": "203", "c": "k10", "src": "自修 p.143 基本學力篇 第 5 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列哪一項處理，無法降低大禮堂的回音干擾？", "o": ["四周掛布幔", "牆壁使用光滑瓷磚", "牆壁噴紙漿使之凹凸不平", "天花板不對稱設計"], "a": 1, "e": "光滑瓷磚會讓聲音反射得更好，回音更嚴重 → 無法降低回音。\n布幔吸音、凹凸不平和不對稱設計讓聲音分散反射，都能降低回音。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-204", "no": "204", "c": "k11", "src": "自修 p.143 基本學力篇 第 6 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "蝙蝠在黑暗無光的洞穴內仍能飛行與捕食，是利用什麼來辨識周圍情況？", "o": ["聽到 100 Hz 以下之回聲來辨識", "利用皮膚對空氣流動感應", "眼睛可看見紅外線", "發出超聲波，接收其反射波來辨識"], "a": 3, "e": "蝙蝠發出超聲波，接收障礙物反射回來的聲波來判斷位置（回聲定位）。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-205", "no": "205", "c": "k10", "src": "自修 p.143 基本學力篇 第 7 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "在乾燥無風、溫度相同的空氣中，回聲與原聲的比較，下列何者不同？", "o": ["速率", "音調", "音色", "響度"], "a": 3, "e": "回聲和原聲在同一空氣中：速率、音調、音色都不變，只有響度變小（能量被吸收、傳得較遠）。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-206", "no": "206", "c": "k8", "src": "自修 p.143 基本學力篇 第 8 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列四聲音皆在 70～80 dB 範圍內，以示波器顯示出在 0.01 秒內之波形，何者最可能是噪音？", "o": ["圖A波形", "圖B波形", "圖C波形", "圖D波形"], "a": 1, "e": "噪音的波形雜亂、沒有規律。四個波形中 (B) 最雜亂 → 最可能是噪音。", "h": [], "rep": false, "img": "s3-q206", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-207", "no": "207", "c": "k11", "src": "自修 p.143 基本學力篇 第 9 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "眼鏡清洗機內放清潔液，把眼鏡置於清潔液中，以超聲波來洗淨眼鏡，是利用超聲波的何種性質？", "o": ["波速特別快", "波形特殊", "高頻率、短波長", "人耳聽不見"], "a": 2, "e": "超音波清洗利用超聲波「高頻率、短波長」的特性，產生快速振動把細小縫隙的髒污震出來。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-208", "no": "208", "c": "k11", "src": "自修 p.143 基本學力篇 第 10 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "有一直昇機在空中定點向地面發出超聲波，經 10 秒後收到回聲，若當時空氣乾燥無風，氣溫為 27 °C，則直昇機距離地面高度為多少公尺？", "o": ["1536", "1636", "1736", "1836"], "a": 2, "e": "27 °C 聲速 v＝331＋0.6×27＝347.2 m/s。\n10 秒是來回：高度＝347.2×10÷2＝1736 公尺。", "h": ["先用 v＝331＋0.6T 算聲速。", "10 秒是來回時間，距離要除以 2。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-209", "no": "209", "c": "k10", "src": "自修 p.143 基本學力篇 第 11 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "聲音遇到下列何種表面時，反射聲音的效果較好？", "o": ["柔軟、粗糙", "柔軟、光滑", "堅硬、粗糙", "堅硬、光滑"], "a": 3, "e": "堅硬、光滑的表面不容易吸收聲音，反射效果最好。柔軟、粗糙的表面會吸音。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-210", "no": "210", "c": "k11", "src": "自修 p.143 基本學力篇 第 12 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "已知人的聽覺範圍在 20 Hz～20000 Hz，而狗的聽覺範圍在 15 Hz～50000 Hz，若要設計一哨子吹出的聲波讓狗可以聽到，而人聽不到，則下列哪一頻率符合？", "o": ["252 Hz", "514 Hz", "2000 Hz", "30000 Hz"], "a": 3, "e": "狗聽得到、人聽不到 → 頻率要大於 20000 Hz 且不超過 50000 Hz → 30000 Hz。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-211", "no": "211", "c": "k5", "src": "自修 p.143 基本學力篇 第 13 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "甲超聲波頻率 25000 Hz、乙超聲波頻率 30000 Hz、丙超聲波頻率 40000 Hz，三者在相同空氣中傳播，何者速率最快？", "o": ["甲", "乙", "丙", "三者相同"], "a": 3, "e": "聲速只由介質決定，和頻率無關 → 三者相同。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-212", "no": "212", "c": "k11", "src": "自修 p.143 基本學力篇 第 14 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列哪一頻率範圍內的聲波在 0 dB 以上時，人耳皆可以聽到？", "o": ["5000 Hz～50000 Hz", "300 Hz～3000 Hz", "5 Hz～500 Hz", "18000 Hz～24000 Hz"], "a": 1, "e": "人耳聽 20～20000 Hz，整段都在範圍內的只有 300～3000 Hz。\n其他選項有一部分超出 20～20000 Hz。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-213", "no": "213", "c": "k11", "src": "自修 p.146 類題演練 第 1 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "探測船在海洋中以頻率 30000 Hz 聲納偵測某處海底深度，聲波在海水中速率為 1500 m / s，經 3.5 秒收到回聲，若改用頻率為 60000 Hz 偵測同一處深度，則經多少秒可收到回聲？", "o": ["1.75 秒", "3.5 秒", "7.0 秒", "10.5 秒"], "a": 1, "e": "海底深度和海水聲速都沒變，換頻率不會改變聲速 → 回聲時間仍是 3.5 秒。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}, {"id": "s3-214", "no": "214", "c": "k10", "src": "自修 p.146 類題演練 第 2 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "在兩峭壁間（非正中央）鳴槍，前後共聽到 3 聲回聲，鳴槍後 1 秒時，聽到第 1 聲回聲，5 秒時，聽到第 3 聲回聲，已知當時聲速為 340 m / s，則兩峭壁距離為多少公尺？", "o": ["2550", "1700", "850", "425"], "a": 2, "e": "第 1 聲回聲來自近的峭壁：來回 1 秒 → 距離＝340×1÷2＝170 m。\n第 3 聲是兩邊各反射一次的聲音，時間＝近壁來回＋遠壁來回＝5 秒 → 遠壁來回 4 秒 → 距離＝340×4÷2＝680 m。\n兩峭壁相距＝170＋680＝850 m。", "h": ["第 1 聲回聲來自較近還是較遠的峭壁？", "第 3 聲回聲的時間＝近壁來回時間＋遠壁來回時間。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "C"}, {"id": "s3-215", "no": "215", "c": "k11", "src": "自修 p.146 類題演練 第 3 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "漁船以 30000 Hz 超聲波偵測水面下魚群位置，經 3 秒收到回聲，已知水中聲速為 1500 m / s，魚群在水面下多少公尺處？", "o": ["2250", "1500", "1125", "750"], "a": 0, "e": "距離＝v×t÷2＝1500×3÷2＝2250 公尺。", "h": ["3 秒是來回時間。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-216", "no": "216", "c": "k5", "src": "自修 p.146 類題演練 第 4 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "承上題，此超聲波在水中的波長為多少公分？", "o": ["5", "10", "20", "40"], "a": 0, "e": "λ＝v÷f＝1500÷30000＝0.05 m＝5 公分。", "h": ["λ＝v÷f，最後換成公分。"], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "A"}, {"id": "s3-217", "no": "217", "c": "k11", "src": "自修 p.147 科學素養篇 第 1 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列哪一聲波，可作為眼鏡清洗機所發出的聲波頻率？", "o": ["1000 Hz", "15000 Hz", "20k Hz", "40k Hz"], "a": 3, "e": "眼鏡清洗機用的是超聲波，頻率要大於 20000 Hz → 40k Hz（40000 Hz）。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "D"}, {"id": "s3-218", "no": "218", "c": "k5", "src": "自修 p.147 科學素養篇 第 2 題", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "三隻蝙蝠分別發出如下頻率超聲波：甲為 24000 Hz、乙為 48000 Hz、丙為 72000 Hz，在同一無風空氣中傳遞，則下列何者正確？", "o": ["週期大小為甲<乙<丙", "聲速快慢為甲＝乙＝丙", "波長大小為甲<乙<丙", "聲波響度為甲<乙<丙"], "a": 1, "e": "同一空氣中，聲速都相同 → (B) 正確。\n頻率愈高週期愈小：甲＞乙＞丙，(A) 錯；頻率愈高波長愈短：甲＞乙＞丙，(C) 錯。\n題目沒有給響度資訊，(D) 錯。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "B"}], "extras": [{"id": "compare", "title": "易混淆比較", "html": "<h3>波動性質綜合對照表</h3><div class=\"tbl\"><table><thead><tr><th>比較項目</th><th>橫波（高低波）</th><th>縱波（疏密波）</th><th>電磁波（非力學波）</th></tr></thead><tbody><tr><td>介質振動方向</td><td>與波行進方向垂直</td><td>與波行進方向平行</td><td>不需要介質（電磁場振動）</td></tr><tr><td>傳播是否需介質</td><td>需要（力學波）</td><td>需要（力學波）</td><td>完全不需要，可在真空傳播</td></tr><tr><td>代表波形特徵</td><td>波峰、波谷、波長、振幅</td><td>密部、疏部、波長</td><td>波形多樣（具波粒二象性）</td></tr><tr><td>生活實例</td><td>水波表面、繩波、彈簧橫波</td><td>空氣聲波、彈簧縱波</td><td>光波、無線電波、微波、X射線</td></tr><tr><td>真空中波速</td><td>0 m/s（無法傳遞）</td><td>0 m/s（無法傳遞）</td><td>約 3 × 10⁸ m/s（光速）</td></tr></tbody></table></div><h3>聲音三要素核心對照表</h3><div class=\"tbl\"><table><thead><tr><th>三要素</th><th>響度（音量）</th><th>音調（音高）</th><th>音色（音品）</th></tr></thead><tbody><tr><td>決定物理量</td><td>振幅（與聲源距離亦有關）</td><td>頻率（振動快慢）</td><td>波形（泛音結構）</td></tr><tr><td>單位</td><td>分貝（dB）</td><td>赫茲（Hz）或 次／秒</td><td>無特定單位（比對波形幾何）</td></tr><tr><td>示波器波形特徵</td><td>波上下起伏的高低幅度</td><td>單位時間內波形排列的疏密程度</td><td>波形外觀的幾何形狀曲折度</td></tr><tr><td>影響調控方式</td><td>施力大小、距發聲體遠近</td><td>物體發聲結構（輕薄短小細緊）</td><td>發聲體材料與構造</td></tr><tr><td>日常辨識實例</td><td>輕敲 vs 重敲鼓面</td><td>尖叫聲 vs 低沉吼聲、男低音女高音</td><td>聞其聲便知何人、鋼琴與吉他合奏</td></tr></tbody></table></div><h3>原聲 vs. 回聲（回音）同介質傳播對照表</h3><div class=\"tbl\"><table><thead><tr><th>物理特性</th><th>原聲</th><th>回聲（回音）</th><th>判定結果</th></tr></thead><tbody><tr><td>傳播速率（v）</td><td>取決於介質狀態</td><td>與原聲處於相同介質，速率相同</td><td>不變</td></tr><tr><td>頻率（f）</td><td>取決於波源</td><td>頻率由原發聲體決定</td><td>不變</td></tr><tr><td>波長（λ）</td><td>λ = v/f</td><td>速率與頻率皆不變，波長必相同</td><td>不變</td></tr><tr><td>週期（T）</td><td>T = 1/f</td><td>頻率不變，週期必相同</td><td>不變</td></tr><tr><td>音色（波形）</td><td>發聲體固有波形</td><td>波形特徵保持一致</td><td>不變</td></tr><tr><td>進行方向</td><td>向障礙物前進</td><td>經界面反射後逆向或折回傳播</td><td>改變</td></tr><tr><td>振幅與響度</td><td>能量較充沛、振幅較大</td><td>因傳播距離增加及界面吸收能量，振幅變小</td><td>變小（變弱）</td></tr></tbody></table></div><h3>管樂吹奏 vs. 敲擊試管試驗對比表</h3><div class=\"tbl\"><table><thead><tr><th>操作方式</th><th>主要振動體</th><th>水量增加（水位升高）時的變化</th><th>水量減少（水位降低）時的變化</th></tr></thead><tbody><tr><td>向管口吹氣</td><td>管內空氣柱</td><td>空氣柱變短 → 振動快 → 音調升高</td><td>空氣柱變長 → 振動慢 → 音調降低</td></tr><tr><td>用湯匙敲擊試管</td><td>水柱與試管壁</td><td>水質量變重 → 振動慢 → 音調降低</td><td>水質量變輕 → 振動快 → 音調升高</td></tr></tbody></table></div>"}, {"id": "timeline", "title": "流程與計算步驟", "html": "<h3>理化聲音傳遞與聽覺感知歷程</h3><div class=\"tbl\"><table><thead><tr><th>步驟階段</th><th>歷程事件</th><th>重點與能量／信號轉換說明</th></tr></thead><tbody><tr><td>步驟一：聲源產生</td><td>物體受力快速振動</td><td>力學動能轉化為空氣分子的彈性疏密擾動（機械縱波）。</td></tr><tr><td>步驟二：介質傳播</td><td>空氣分子形成疏密交替波形</td><td>分子在原處前後振動，波速由環境氣溫決定（v = 331 + 0.6T），能量向外擴散。</td></tr><tr><td>步驟三：外耳收集</td><td>耳廓收集聲波，經外耳道傳遞</td><td>聲波能量推動鼓膜產生同頻率的機械振動。</td></tr><tr><td>步驟四：中耳放大</td><td>三塊聽小骨（錘骨、砧骨、鐙骨）槓桿傳動</td><td>將鼓膜傳來的聲波微弱振動等比例物理性放大，傳入卵圓窗。</td></tr><tr><td>步驟五：內耳轉換</td><td>耳蝸內液體產生壓力波擾動基底膜</td><td>基底膜纖毛依長度與不同頻率產生共振，將機械能轉換為聽神經動作電位信號。</td></tr><tr><td>步驟六：大腦解讀</td><td>聽覺神經傳送至大腦皮質聽覺區</td><td>大腦將電信號解譯為音調、響度與音色，形成聽覺認知。</td></tr></tbody></table></div><h3>聲納與回聲測距思考計算流程</h3><div class=\"tbl\"><table><thead><tr><th>步驟階段</th><th>運算流程步驟</th><th>計算重點與核心公式</th></tr></thead><tbody><tr><td>步驟一：確認聲速</td><td>計算當時環境下的聲速 v</td><td>依氣溫帶入 v = 331 + 0.6T（如 15°C 為 340 m/s；海水中聲速約 1500 m/s）。</td></tr><tr><td>步驟二：核算時間</td><td>判定所給時間 t 是單程還是來回雙程</td><td>題目若給「發出至接收到回聲的時間」，此為雙程時間。</td></tr><tr><td>步驟三：代入測距公式</td><td>靜止測距：S ＝ v × t ÷ 21, 26</td><td>距離＝聲速 × 單程時間；務必記得除以 2。</td></tr><tr><td>步驟四：運動聲源修正</td><td>船隻／蝙蝠面對山壁前進或遠離</td><td>1. 向山壁前進：S（鳴笛處）＝（v聲 ＋ v船）× t ÷ 2； 2. 背離山壁前進：S（鳴笛處）＝（v聲 － v船）× t ÷ 2。</td></tr></tbody></table></div>"}, {"id": "charts", "title": "圖表判讀", "html": "<h3>橫波波形幾何圖（位移—位置坐標圖）</h3><p class=\"li\"><b>要看懂什麼</b>：</p><p class=\"li sub\">• 橫軸代表位置（距離，單位 cm 或 m），縱軸代表質點離開平衡位置的位移。</p><p class=\"li sub\">• 能精確標記出波峰、波谷、平衡位置、振幅及波長。</p><p class=\"li\"><b>常見判讀方式</b>：</p><p class=\"li sub\">• <b>波長（λ）判讀</b>：任選一個波峰到下一個相鄰波峰的水平距離，或一個「完整的 S 型正弦波」佔用的水平寬度。</p><p class=\"li sub\">• <b>振幅判讀</b>：中心平衡線到波峰頂點的<b>垂直距離</b>（切忌誤取波峰到波谷的全高）。</p><p class=\"li sub\">• <b>質點下一瞬間運動方向（微移法）</b>：將原波形依波前進方向稍微平行移動一段微小距離（畫出虛線波形），原波形上的質點垂直畫箭頭指向虛線波形，箭頭所指即為該質點此刻運動方向。</p><h3>示波器波形圖（聲音三要素判讀）</h3><p class=\"li\"><b>要看懂什麼</b>：</p><p class=\"li sub\">• 示波器將麥克風收集到的縱波壓力變化轉換為螢幕上的橫波圖形。</p><p class=\"li sub\">• 透過波形圖外觀直接比對不同聲音的「響度大小」、「音調高低」與「音色種類」。</p><p class=\"li\"><b>常見判讀方式</b>：</p><p class=\"li sub\">• <b>判讀響度</b>：看波形上下起伏的<b>振幅高度</b>。振幅愈高，響度（分貝）愈大。</p><p class=\"li sub\">• <b>判讀音調</b>：看固定時間橫軸內<b>波的密集程度（頻率）</b>。相同時間範圍內波形個數愈多，頻率愈高，音調愈高。</p><p class=\"li sub\">• <b>判讀音色</b>：看波形的<b>幾何形狀曲線</b>。純音叉為平滑單純的正弦波，鋼琴、長笛、小提琴或人聲則呈現各自規則但複雜的疊加波形；若完全雜亂無章則為噪音。</p><h3>空氣中聲波縱波與位移轉換圖</h3><p class=\"li\"><b>要看懂什麼</b>：</p><p class=\"li sub\">• 理解縱波之密部（分子聚集）、疏部（分子稀疏）與質點振動作圖的對應關係。</p><p class=\"li\"><b>常見判讀方式</b>：</p><p class=\"li sub\">• 規定質點向右位移為正（圖形上方波峰）、向左位移為負（圖形下方波谷）。</p><p class=\"li sub\">• <b>密部中心與疏部中心</b>：瞬間位移皆為 0（恰位於轉換圖的平衡軸上）。</p><p class=\"li sub\">• 密部中心左側質點向右移動（位移為正），右側質點向左移動（位移為負），分子在此聚集形成密部。</p><h3>聲音反射與回聲測距時序圖</h3><p class=\"li\"><b>要看懂什麼</b>：</p><p class=\"li sub\">• 障礙物反射界面之法線、入射線與反射線幾何關係。</p><p class=\"li sub\">• 聲納探測脈衝信號與接收信號在時間軸上的峰值間隔。</p><p class=\"li\"><b>常見判讀方式</b>：</p><p class=\"li sub\">• <b>角度判定</b>：入射角與反射角皆為「聲線與法線（垂直於反射面）的夾角」，且兩者嚴格相等。</p><p class=\"li sub\">• <b>時間差判定</b>：發射波強度最大（第 1 個脈衝尖峰），經時間 Delta t 後收到微弱脈衝（回聲），兩峰的時間間隔即為雙程時間 t，距離 S = v × Delta t/2。</p>"}, {"id": "tips", "title": "口訣與防錯", "html": "<h3>理化關鍵必背口訣</h3><p class=\"li\"><b>發聲體音調變化口訣</b>：</p><div class=\"poem\"><b>「輕、薄、短、小、細、緊，音調高！」</b>（敲擊或撥弄物體時，質量愈小、形體愈短細、繃得愈緊，振動頻率愈高，發出聲音愈尖銳。）</div><p class=\"li\"><b>介質與波速口訣</b>：</p><div class=\"poem\"><b>「固大於液，液大於氣；介質決定傳播速度，波源決定振動頻率。」</b>（同一均勻介質中波速固定不變，不管大聲喊還是小聲喊、男低音還是女高音，傳播速度通通一樣快。）</div><p class=\"li\"><b>氣溫與聲速公式口訣</b>：</p><div class=\"poem\"><b>「零度三三一，每度加零點六。」</b>（v = 331 + 0.6T）</div><p class=\"li\"><b>反射與回聲判斷口訣</b>：</p><div class=\"poem\"><b>「同介質回聲速不變，波長頻率照原本；只有能量被削弱，振幅變小方向轉。」</b></div><p class=\"li\"><b>回聲距離計算口訣</b>：</p><div class=\"poem\"><b>「看到回聲除以二，單程雙程先分清！」</b></div>"}]});
